:root {
  --ink: #07070c;
  --paper: #f5f1e8;
  --muted: #a9a5b8;
  --pink: #ff2e7e;
  --pink-soft: #ff7cb1;
  --cyan: #66f4ff;
  --gold: #ffc857;
  --green: #6dffa6;
  --violet: #8d5bff;
  --panel: rgba(10, 9, 18, 0.66);
  --line: rgba(255, 255, 255, 0.14);
  --font-display: "Arial Black", "Helvetica Neue", Impact, sans-serif;
  --font-ui: "Helvetica Neue", "Segoe UI", Arial, sans-serif;
  --font-mono: "SFMono-Regular", "Roboto Mono", "Courier New", monospace;
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-right: env(safe-area-inset-right, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-left: env(safe-area-inset-left, 0px);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #07070c;
  color: var(--paper);
  font-family: var(--font-ui);
  -webkit-user-select: none;
  user-select: none;
  overscroll-behavior: none;
}

body { touch-action: none; }

#app { position: fixed; inset: 0; overflow: hidden; }

#stage { position: absolute; inset: 0; background: radial-gradient(circle at 70% 30%, #262040 0%, #080811 62%, #05050a 100%); }
#stage canvas { display: block; width: 100%; height: 100%; outline: none; }

kbd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 1.55em;
  height: 1.55em;
  padding: 0 0.36em;
  border: 1px solid rgba(255, 255, 255, 0.22);
  border-bottom-color: rgba(255, 255, 255, 0.09);
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.07);
  color: #fff;
  font-family: var(--font-mono);
  font-size: 0.64em;
  font-weight: 700;
  letter-spacing: 0.06em;
  box-shadow: 0 1px 0 rgba(0, 0, 0, 0.35);
}

/* ---------------------------------------------------------------- HUD */

#hud {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.7s ease 0.12s;
  z-index: 20;
  padding: calc(20px + var(--safe-top)) calc(22px + var(--safe-right)) calc(20px + var(--safe-bottom)) calc(22px + var(--safe-left));
}
body.playing #hud { opacity: 1; }

.hud-top-left { position: absolute; top: calc(18px + var(--safe-top)); left: calc(20px + var(--safe-left)); }
.hud-top-right { position: absolute; top: calc(18px + var(--safe-top)); right: calc(20px + var(--safe-right)); display: flex; flex-direction: column; align-items: flex-end; gap: 8px; }
.hud-bottom-left { position: absolute; bottom: calc(22px + var(--safe-bottom)); left: calc(22px + var(--safe-left)); }
.hud-bottom-right { position: absolute; bottom: calc(22px + var(--safe-bottom)); right: calc(22px + var(--safe-right)); }

.minimap-wrap {
  position: relative;
  width: 176px;
  height: 176px;
  border-radius: 50%;
  padding: 4px;
  background: linear-gradient(145deg, rgba(255, 255, 255, 0.42), rgba(255, 255, 255, 0.05) 55%);
  filter: drop-shadow(0 10px 22px rgba(0, 0, 0, 0.46));
}
#minimap {
  width: 100%;
  height: 100%;
  border-radius: 50%;
  display: block;
  background: #0c1020;
}
.minimap-ring {
  position: absolute;
  inset: 3px;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.24);
  box-shadow: inset 0 0 30px rgba(3, 4, 10, 0.75);
  pointer-events: none;
}
.minimap-ring::after {
  content: "";
  position: absolute;
  inset: 13px;
  border-radius: 50%;
  border: 1px dashed rgba(102, 244, 255, 0.18);
}
.minimap-north {
  position: absolute;
  top: -7px;
  left: 50%;
  transform: translateX(-50%);
  width: 22px;
  height: 22px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #0b0b14;
  border: 1px solid rgba(255, 255, 255, 0.28);
  color: var(--cyan);
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.08em;
}
.district-line {
  display: flex;
  align-items: center;
  gap: 7px;
  margin: 8px 0 2px 5px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1.9px;
  color: rgba(255, 255, 255, 0.72);
  text-shadow: 0 1px 6px #000;
}
.district-dot { width: 3px; height: 3px; border-radius: 50%; background: var(--pink); }
.cash-line {
  margin-left: 4px;
  font-family: var(--font-display);
  font-size: 30px;
  letter-spacing: 0.01em;
  color: var(--green);
  text-shadow: 0 0 24px rgba(109, 255, 166, 0.32), 0 2px 0 rgba(0, 0, 0, 0.5);
  font-variant-numeric: tabular-nums;
  line-height: 1;
}
.cash-symbol { font-size: 21px; margin-right: 1px; opacity: 0.9; }

.wanted { display: flex; gap: 1px; filter: drop-shadow(0 2px 4px #000); }
.wanted .star {
  font-size: 22px;
  line-height: 1;
  color: rgba(255, 255, 255, 0.13);
  transition: color 0.18s ease, text-shadow 0.18s ease, transform 0.18s ease;
}
.wanted .star.on { color: #ffd15c; text-shadow: 0 0 14px rgba(255, 190, 60, 0.85); transform: scale(1.06); }

.mission-card {
  width: 238px;
  padding: 12px 14px 11px;
  border: 1px solid var(--line);
  border-left: 2px solid var(--cyan);
  background: linear-gradient(120deg, rgba(9, 11, 22, 0.86), rgba(9, 11, 22, 0.5));
  backdrop-filter: blur(14px);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 12px), calc(100% - 12px) 100%, 0 100%);
  box-shadow: 0 12px 34px rgba(0, 0, 0, 0.34);
  transition: opacity 0.4s ease, transform 0.4s ease;
}
.mission-card.hidden { opacity: 0; transform: translateX(18px); }
.mission-eyebrow {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 2.1px;
  color: var(--cyan);
  margin-bottom: 4px;
}
.pulse-dot { width: 5px; height: 5px; border-radius: 50%; background: var(--cyan); box-shadow: 0 0 8px var(--cyan); animation: pulse 1.6s infinite; }
@keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.25; } }
.mission-title { font-family: var(--font-display); font-size: 18px; letter-spacing: 0.02em; line-height: 1; }
.mission-target { margin-top: 5px; font-size: 10px; color: rgba(255, 255, 255, 0.62); letter-spacing: 0.3px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mission-meta { display: flex; justify-content: space-between; margin-top: 7px; font-family: var(--font-mono); font-size: 11px; font-weight: 700; color: #fff; }
.mission-meta #mission-timer { color: var(--gold); }
.mission-bar { height: 2px; margin-top: 7px; background: rgba(255, 255, 255, 0.12); overflow: hidden; }
.mission-bar i { display: block; height: 100%; width: 100%; background: linear-gradient(90deg, var(--cyan), var(--pink)); transition: width 0.3s linear; }

.radio-pill {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 6px 5px 10px;
  border: 1px solid var(--line);
  border-radius: 99px;
  background: rgba(8, 8, 16, 0.5);
  backdrop-filter: blur(10px);
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 1.4px;
  color: rgba(255, 255, 255, 0.63);
}
.eq { display: flex; align-items: flex-end; gap: 2px; height: 10px; }
.eq i { width: 2px; background: var(--pink); animation: eq 0.9s ease-in-out infinite alternate; }
.eq i:nth-child(1) { height: 4px; animation-delay: 0s; }
.eq i:nth-child(2) { height: 9px; animation-delay: 0.18s; }
.eq i:nth-child(3) { height: 6px; animation-delay: 0.36s; }
.eq i:nth-child(4) { height: 10px; animation-delay: 0.1s; }
@keyframes eq { to { height: 2px; } }
body.muted .eq i { animation-play-state: paused; height: 2px; opacity: 0.4; }
.icon-btn {
  pointer-events: auto;
  width: 22px; height: 22px;
  display: grid; place-items: center;
  border: 0; border-radius: 50%;
  background: rgba(255, 255, 255, 0.1);
  color: #fff; font-size: 11px; cursor: pointer;
}
.icon-btn:hover { background: rgba(255, 255, 255, 0.2); }

.stat-row { display: flex; align-items: center; gap: 8px; margin-bottom: 5px; }
.stat-label { width: 44px; font-size: 7.5px; font-weight: 900; letter-spacing: 1.6px; color: rgba(255, 255, 255, 0.55); }
.stat-bar { width: 138px; height: 5px; background: rgba(255, 255, 255, 0.13); border-radius: 99px; overflow: hidden; }
.stat-bar i { display: block; height: 100%; width: 100%; background: linear-gradient(90deg, #34e58b, #a6ff74); border-radius: 99px; transition: width 0.25s ease; box-shadow: 0 0 8px rgba(84, 255, 140, 0.45); }
.stat-bar.armor i { background: linear-gradient(90deg, #3d8bff, #75e4ff); box-shadow: 0 0 8px rgba(80, 160, 255, 0.5); }
.armor-row { opacity: 0.9; }
.stat-value { font-family: var(--font-mono); font-size: 9px; color: rgba(255, 255, 255, 0.65); width: 20px; text-align: right; }
.hint-line { margin-top: 9px; font-size: 8px; font-weight: 700; letter-spacing: 0.8px; color: rgba(255, 255, 255, 0.32); }
