.speedo small { font-size: 8px; font-weight: 900; letter-spacing: 1.2px; color: rgba(255, 255, 255, 0.5); }
.gear { margin-left: 5px; width: 24px; height: 24px; display: grid; place-items: center; border: 1px solid rgba(255, 255, 255, 0.22); border-radius: 4px; font-family: var(--font-mono); font-size: 12px; color: var(--cyan); background: rgba(102, 244, 255, 0.08); }
.v-meta { display: flex; justify-content: flex-end; gap: 10px; margin-top: 2px; font-size: 7.5px; font-weight: 800; letter-spacing: 1.4px; color: rgba(255, 255, 255, 0.55); }
.battery { display: flex; align-items: center; gap: 6px; margin-top: 6px; justify-content: flex-end; }
