    group.add(bed)
    const bumper = roundedBox(width * 1.01, 0.2, 0.24, 0.03, darkTrimMat)
    bumper.position.set(0, 0.52, length / 2 - 0.02)
    group.add(bumper)
    const strip = new THREE.Mesh(new THREE.BoxGeometry(width * 0.78, 0.035, 0.04), headlightMat)
    strip.position.set(0, 0.92, length / 2 - 0.03)
    group.add(strip)
    addGlow(group, _glowTex, 0xe8f8ff, width * 0.9, new THREE.Vector3(0, 0.92, length / 2), 0.7)
    const rear = addLightBar(group, type, length / 2, -length / 2, 1.32, 0.9)
    // fender flares
    for (const x of [-1, 1]) {
      for (const z of [type.wheelbase / 2, -type.wheelbase / 2]) {
        const flare = roundedBox(0.16, 0.1, 1.28, 0.04, darkTrimMat)
        flare.position.set(x * (width / 2 - 0.02), wheelRadius + 0.5, z)
        group.add(flare)
      }
    }
  } else {
    // Generic modern EV body: low slung for hyper/sedan, tall for SUV/truck
    const tall = shape === 'suv' || shape === 'truck' ? 1 : 0
    const h = 0.56 + tall * 0.18
    const body = roundedBox(width, h, length * 0.94, shape === 'hyper' ? 0.24 : 0.18, bodyMat)
    body.position.y = bodyY
    group.add(body)

    // nose and tail
    const nose = roundedBox(width * 0.93, 0.22 + tall * 0.08, length * 0.22, 0.1, bodyMat)
    nose.position.set(0, 0.7 + tall * 0.12, length * 0.36)
    group.add(nose)
    const tail = roundedBox(width * 0.92, 0.26 + tall * 0.1, length * 0.18, 0.1, bodyMat)
    tail.position.set(0, 0.72 + tall * 0.12, -length * 0.39)
    group.add(tail)

    // cabin
    const cabinLen = length * (shape === 'hyper' ? 0.33 : shape === 'compact' ? 0.42 : 0.4)
    const cabinHeight = shape === 'hyper' ? 0.42 : shape === 'suv' ? 0.7 : shape === 'truck' ? 0.62 : 0.55
    const cabin = roundedBox(width * (shape === 'hyper' ? 0.68 : 0.8), cabinHeight, cabinLen, 0.16, glassMat)
    cabin.position.set(0, bodyY + h / 2 + cabinHeight / 2 - 0.03, -length * (shape === 'compact' ? 0.05 : 0.09))
    group.add(cabin)

    // roof cap
    const roof = roundedBox(width * (shape === 'hyper' ? 0.56 : 0.68), 0.06, cabinLen * 0.82, 0.03, bodyMat)
    roof.position.set(0, cabin.position.y + cabinHeight / 2 + 0.005, cabin.position.z + 0.02)
    group.add(roof)
    if (shape === 'suv' || shape === 'truck') {
      const railMat = new THREE.MeshStandardMaterial({ color: 0x2a2d36, metalness: 0.8, roughness: 0.35 })
      for (const x of [-0.65, 0.65]) {
        const rail = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.05, cabinLen * 0.8), railMat)
        rail.position.set(x, roof.position.y + 0.06, roof.position.z)
        group.add(rail)
      }
    }

    // dark lower trim + bumpers
    const skirt = roundedBox(width * 1.01, 0.16, length * 0.6, 0.05, darkTrimMat)
    skirt.position.y = 0.41 + rideHeight * 0.2
    group.add(skirt)
    const frontBumper = roundedBox(width * 1.01, 0.22, 0.24, 0.05, darkTrimMat)
    frontBumper.position.set(0, 0.52, length / 2 - 0.04)
    group.add(frontBumper)
    const rearBumper = roundedBox(width * 1.01, 0.22, 0.2, 0.05, darkTrimMat)
    rearBumper.position.set(0, 0.52, -length / 2 + 0.04)
    group.add(rearBumper)

    // headlight strip + taillight strip
    const rear = addLightBar(group, type, length / 2 + 0.005, -length / 2 - 0.005, 0.78 + tall * 0.2, 0.78 + tall * 0.2)

    // side accent
    if (shape !== 'compact') {
      for (const x of [-1, 1]) {
        const blade = new THREE.Mesh(new THREE.BoxGeometry(0.025, 0.045, length * 0.44), accentMat)
        blade.position.set(x * (width / 2 + 0.005), 0.63 + tall * 0.2, -0.2)
        group.add(blade)
      }
    }

    // mirrors
    for (const x of [-1, 1]) {
      const mirror = roundedBox(0.15, 0.09, 0.25, 0.03, bodyMat)
      mirror.position.set(x * (width / 2 + 0.1), cabin.position.y - 0.02, cabin.position.z + cabinLen * 0.38)
      group.add(mirror)
    }

    // spoiler for hyper
    if (shape === 'hyper') {
      const wing = roundedBox(width * 0.82, 0.05, 0.3, 0.02, darkTrimMat)
      wing.position.set(0, 1.03, -length * 0.43)
      group.add(wing)
      for (const x of [-0.6, 0.6]) {
        const strut = new THREE.Mesh(new THREE.BoxGeometry(0.04, 0.2, 0.1), darkTrimMat)
        strut.position.set(x, 0.9, -length * 0.42)
        group.add(strut)
      }
    }

    // truck bed
    if (shape === 'truck') {
      const bed = roundedBox(width * 0.86, 0.14, length * 0.34, 0.04, darkTrimMat)
      bed.position.set(0, 1.38, -length * 0.3)
      group.add(bed)
      for (const x of [-0.72, 0.72]) {
        const wall = roundedBox(0.08, 0.24, length * 0.34, 0.02, bodyMat)
        wall.position.set(x, 1.48, -length * 0.3)
        group.add(wall)
      }
    }

    // police livery
    if (type.id === 'apex') {
      const white = new THREE.MeshStandardMaterial({ color: 0xe8edf4, metalness: 0.35, roughness: 0.4 })
      for (const x of [-1, 1]) {
        const door = roundedBox(0.03, 0.34, 1.45, 0.01, white)
        door.position.set(x * (width / 2 + 0.012), 0.69, -0.06)
        group.add(door)
      }
      const bar = new THREE.Mesh(new THREE.BoxGeometry(1.24, 0.1, 0.24), new THREE.MeshBasicMaterial({ color: 0x14213a }))
      bar.position.set(0, roof.position.y + 0.12, roof.position.z)
      group.add(bar)
      const red = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.11, 0.18), new THREE.MeshBasicMaterial({ color: 0xff2030, toneMapped: false }))
      red.position.set(-0.33, roof.position.y + 0.2, roof.position.z)
      group.add(red)
      const blue = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.11, 0.18), new THREE.MeshBasicMaterial({ color: 0x2070ff, toneMapped: false }))
      blue.position.set(0.33, roof.position.y + 0.2, roof.position.z)
      group.add(blue)
      group.userData.policeLights = [red, blue]
      addGlow(group, _glowTex, 0xff3040, 1.2, new THREE.Vector3(-0.33, roof.position.y + 0.24, roof.position.z), 0.5)
      addGlow(group, _glowTex, 0x3080ff, 1.2, new THREE.Vector3(0.33, roof.position.y + 0.24, roof.position.z), 0.5)
    }

    group.userData.rearLight = rear
  }

  const wheels = buildWheels(group, type, ai)

  // underglow — a defining modern-EV cue
  if (!ai) {
    const glow = new THREE.Mesh(
      new THREE.PlaneGeometry(width * 1.3, length * 1.02),
      new THREE.MeshBasicMaterial({
        map: _glowTex, color: type.accent, transparent: true, opacity: 0.34,
        blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false,
      }),
    )
    glow.rotation.x = -Math.PI / 2
    glow.position.y = 0.055
    glow.renderOrder = 3
    group.add(glow)
  }

  addBlobShadow(group, Math.max(width, length) * 0.66, 0.9, 0.035)

  const vehicle = {
    group, type, wheels, width, length, wheelRadius, rideHeight,
    collisionRadius: Math.max(width * 0.62, 0.6),
    label: null,
    headlights: [],
  }

  group.userData.vehicle = vehicle
  return vehicle
}

const labelTexCache = new Map()
export function addVehicleLabel(vehicle) {
  const t = vehicle.type
  if (!labelTexCache.has(t.id)) labelTexCache.set(t.id, labelTexture(t.name, t.className, `#${t.accent.toString(16).padStart(6, '0')}`))
  const mat = new THREE.SpriteMaterial({ map: labelTexCache.get(t.id), transparent: true, depthWrite: false, toneMapped: false })
  const sprite = new THREE.Sprite(mat)
  sprite.scale.set(4.5, 1.125, 1)
  sprite.position.set(0, t.shape === 'bike' ? 2.1 : t.shape === 'cyber' ? 2.55 : 2.35, 0)
  sprite.userData.baseY = sprite.position.y
  vehicle.group.add(sprite)
  vehicle.label = sprite
  return sprite
}

export function updateVehicleVisuals(vehicle, speed, steer, dt, braking = false, elapsed = 0) {
  for (const w of vehicle.wheels) {
    if (w.front) w.pivot.rotation.y = steer
    w.spin.rotation.x -= (speed * dt) / Math.max(0.2, vehicle.wheelRadius)
  }
  const tail = vehicle.group.userData.rearLight
  if (tail && tail.material) {
    tail.material.color.setHex(braking ? 0xff5a4a : 0xff1838)
    tail.scale.y = braking ? 1.5 : 1
  }
  const pl = vehicle.group.userData.policeLights
  if (pl) {
    const phase = Math.floor(elapsed * 6) % 2
    pl[0].visible = phase === 0
    pl[1].visible = phase === 1
  }
  if (vehicle.label) {
    vehicle.label.position.y = vehicle.label.userData.baseY + Math.sin(elapsed * 1.6) * 0.06
    const dist = vehicle.group.position.distanceTo(vehicle.label.parent.parent?.position || vehicle.group.position)
    vehicle.label.visible = true
  }
}

export function trafficTypeFor(typeIndex, color) {
  const base = { ...VEHICLE_TYPES[typeIndex], color, accent: color, label: null }
  return base
}

import * as THREE from 'three'
import { RoundedBoxGeometry } from 'three/addons/geometries/RoundedBoxGeometry.js'
import { addBlobShadow } from './utils.js'

const skinTones = [0x8f5c3e, 0x6b422c, 0xc58f6b, 0x4d2f22, 0xe0b08c, 0x9c6a4a]
const jeans = [0x2c3b57, 0x30364a, 0x3e4a60, 0x26303f, 0x4a4f5c]
const hoodies = [0x2f6b4f, 0x374255, 0x6c2f42, 0xb48a45, 0x2e566c, 0x7b5a3d, 0x45414f]

function limb(mat, w, h, d, radius = 0.06) {
  return new THREE.Mesh(new RoundedBoxGeometry(w, h, d, 2, Math.min(radius, h / 2.1)), mat)
}

export function createCharacter({
  player = false,
  hoodie = 0x2f6b4f,
  pants = 0x2c3b57,
  skin = 0x8f5c3e,
  cap = true,
  capColor = 0x151a20,
} = {}) {
  const root = new THREE.Group()
  root.name = player ? 'player' : 'pedestrian'

  const skinMat = new THREE.MeshStandardMaterial({ color: skin, roughness: 0.72, metalness: 0 })
  const hoodieMat = new THREE.MeshStandardMaterial({ color: hoodie, roughness: 0.82, metalness: 0.02 })
  const pantsMat = new THREE.MeshStandardMaterial({ color: pants, roughness: 0.9, metalness: 0.01 })
  const shoeMat = new THREE.MeshStandardMaterial({ color: player ? 0xe9e4d8 : 0x24252c, roughness: 0.6, metalness: 0.08 })
  const capMat = new THREE.MeshStandardMaterial({ color: capColor, roughness: 0.76 })
  const chainMat = new THREE.MeshStandardMaterial({ color: 0xffc857, metalness: 0.9, roughness: 0.25 })

  const hips = new THREE.Group()
  hips.position.y = 0.92
  root.add(hips)

  const torso = limb(hoodieMat, 0.5, 0.62, 0.29, 0.14)
  torso.position.y = 0.36
  hips.add(torso)

  if (player) {
    const hood = limb(hoodieMat, 0.34, 0.2, 0.2, 0.08)
    hood.position.set(0, 0.52, -0.18)
    hips.add(hood)
    const chain = new THREE.Mesh(new THREE.TorusGeometry(0.12, 0.014, 5, 12, Math.PI * 0.9), chainMat)
    chain.position.set(0, 0.52, 0.16)
    chain.rotation.x = Math.PI / 2
    chain.rotation.z = Math.PI
    hips.add(chain)
  }

  const neck = new THREE.Mesh(new THREE.CylinderGeometry(0.07, 0.08, 0.1, 8), skinMat)
  neck.position.y = 0.69
  hips.add(neck)

  const head = new THREE.Mesh(new THREE.SphereGeometry(0.15, 14, 10), skinMat)
  head.scale.set(0.95, 1.05, 0.92)
  head.position.y = 0.84
  hips.add(head)

  if (cap) {
    const crown = new THREE.Mesh(new THREE.SphereGeometry(0.158, 14, 8, 0, Math.PI * 2, 0, Math.PI * 0.55), capMat)
    crown.position.y = 0.885
    crown.scale.y = 0.8
    hips.add(crown)
    const brim = new THREE.Mesh(new THREE.BoxGeometry(0.26, 0.025, 0.17), capMat)
    brim.position.set(0, 0.875, 0.15)
    brim.rotation.x = 0.08
    hips.add(brim)
  } else {
    const hair = new THREE.Mesh(new THREE.SphereGeometry(0.153, 12, 8, 0, Math.PI * 2, 0, Math.PI * 0.5), capMat)
    hair.position.y = 0.86
    hips.add(hair)
  }

  const shoulders = new THREE.Group()
  shoulders.position.y = 0.55
  hips.add(shoulders)

  const arms = []
  for (const side of [-1, 1]) {
    const pivot = new THREE.Group()
    pivot.position.set(side * 0.32, 0.0, 0)
    const arm = limb(hoodieMat, 0.15, 0.5, 0.16, 0.07)
    arm.position.y = -0.24
    pivot.add(arm)
    const hand = new THREE.Mesh(new THREE.SphereGeometry(0.075, 8, 6), skinMat)
    hand.position.y = -0.5
    pivot.add(hand)
    if (player) {
      const sleeve = new THREE.Mesh(new THREE.BoxGeometry(0.16, 0.08, 0.17), new THREE.MeshStandardMaterial({ color: 0xe8e4da, roughness: 0.8 }))
      sleeve.position.y = -0.3
      pivot.add(sleeve)
    }
    shoulders.add(pivot)
    arms.push(pivot)
  }

  const legs = []
  for (const side of [-1, 1]) {
    const pivot = new THREE.Group()
    pivot.position.set(side * 0.13, -0.02, 0)
    const leg = limb(pantsMat, 0.2, 0.62, 0.22, 0.08)
    leg.position.y = -0.34
    pivot.add(leg)
    const shoe = limb(shoeMat, 0.22, 0.12, 0.36, 0.05)
    shoe.position.set(0, -0.66, 0.05)
    pivot.add(shoe)
    hips.add(pivot)
    legs.push(pivot)
  }

  addBlobShadow(root, player ? 1.15 : 0.95, 0.7, 0.03)

  const character = {
    root,
    hips,
    torso,
    head,
    arms,
    legs,
    player,
    phase: Math.random() * 10,
    riding: false,
    dead: false,
    materials: { hoodieMat, pantsMat, skinMat },
  }
  root.userData.character = character
  return character
}

export function animateCharacter(char, speed, dt, { riding = false, t = 0 } = {}) {
  if (char.dead) {
    char.hips.rotation.z = THREE.MathUtils.lerp(char.hips.rotation.z, Math.PI / 2, 0.15)
    char.root.position.y = 0.3
    return
  }
  if (riding) {
    char.arms[0].rotation.x = -1.15
    char.arms[1].rotation.x = -1.15
    char.arms[0].rotation.z = 0.15
    char.arms[1].rotation.z = -0.15
    char.legs[0].rotation.x = -1.05
    char.legs[0].rotation.z = 0.25
    char.legs[1].rotation.x = -1.05
    char.legs[1].rotation.z = -0.25
    char.torso.rotation.x = 0.22
    return
  }
  const moving = speed > 0.25
  char.phase += dt * (moving ? speed * 2.1 : 1.1)
  const amp = moving ? Math.min(0.85, 0.28 + speed * 0.1) : 0.035
  const swing = Math.sin(char.phase * 2) * amp
  char.legs[0].rotation.x = swing
  char.legs[1].rotation.x = -swing
  char.arms[0].rotation.x = -swing * 0.85
  char.arms[1].rotation.x = swing * 0.85
  char.arms[0].rotation.z = 0.04
  char.arms[1].rotation.z = -0.04
  char.legs.forEach((l) => { l.rotation.z = 0 })
  char.torso.rotation.x = moving ? 0.09 + Math.min(0.1, speed * 0.02) : Math.sin(t * 1.2) * 0.014
  char.torso.rotation.z = moving ? Math.sin(char.phase * 2) * 0.035 : 0
  char.hips.position.y = 0.92 + (moving ? Math.abs(Math.sin(char.phase * 2)) * 0.035 : Math.sin(t * 1.4) * 0.008)
}

export function createPedestrian(seed = 0, palette = {}) {
  const skin = palette.skin ?? skinTones[seed % skinTones.length]
  const hoodie = palette.hoodie ?? hoodies[(seed * 3 + 1) % hoodies.length]
  const pants = palette.pants ?? jeans[(seed * 5 + 2) % jeans.length]
  return createCharacter({ skin, hoodie, pants, cap: seed % 3 !== 0, capColor: seed % 2 ? 0x1b1e24 : 0x5b3a2b })
}

import * as THREE from 'three'
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js'
import {
  asphaltTexture, sidewalkTexture, sandTexture, grassTexture, facadeTextures,
  canvas2d, canvasTexture, glowTexture, signTexture, addGlow, makeRng, clamp,
} from './utils.js'

export const CITY = {
  n: 5,
  blockSize: 48,
  road: 16,
  pitch: 64,
  min: -168,
  max: 168,
}
CITY.roadCenters = Array.from({ length: CITY.n + 1 }, (_, i) => CITY.min + CITY.road / 2 + i * CITY.pitch)
CITY.blockCenters = Array.from({ length: CITY.n }, (_, i) => CITY.min + CITY.road + CITY.blockSize / 2 + i * CITY.pitch)

const PALETTE = {
  sun: 0xffb27c,
  fog: 0x5c4364,
}

/* ------------------------------------------------------------------ helpers */

function groundGlow(texture, color, size, opacity = 0.45) {
  const mat = new THREE.MeshBasicMaterial({
    map: texture, color, transparent: true, opacity,
    blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false,
  })
  const mesh = new THREE.Mesh(new THREE.PlaneGeometry(size, size), mat)
  mesh.rotation.x = -Math.PI / 2
  mesh.renderOrder = 1
  return mesh
}

function makeCloudTexture() {
  const { c, ctx } = canvas2d(512, 256)
  for (let i = 0; i < 22; i++) {
    const x = 40 + Math.random() * 432
    const y = 90 + Math.random() * 100
    const r = 28 + Math.random() * 72
    const g = ctx.createRadialGradient(x, y, 0, x, y, r)
    g.addColorStop(0, 'rgba(255,220,220,0.36)')
    g.addColorStop(0.55, 'rgba(255,190,190,0.14)')
    g.addColorStop(1, 'rgba(255,190,190,0)')
    ctx.fillStyle = g
    ctx.fillRect(x - r, y - r, r * 2, r * 2)
  }
  return canvasTexture(c)
}

function makeStarTexture() {
  const { c, ctx } = canvas2d(64, 64)
  ctx.translate(32, 32)
  ctx.fillStyle = '#fff'
  ctx.beginPath()
  for (let i = 0; i < 4; i++) {
    const a = (i / 4) * Math.PI * 2
    ctx.lineTo(Math.cos(a) * 30, Math.sin(a) * 30)
    ctx.lineTo(Math.cos(a + Math.PI / 4) * 8, Math.sin(a + Math.PI / 4) * 8)
  }
  ctx.closePath()
  ctx.fill()
  return canvasTexture(c)
}

/* --------------------------------------------------------------------- sky */

function createSky(scene, sunDir) {
  const skyGeo = new THREE.SphereGeometry(820, 40, 28)
  const skyMat = new THREE.ShaderMaterial({
    side: THREE.BackSide,
    depthWrite: false,
    fog: false,
    uniforms: {
      uTop: { value: new THREE.Color(0x10142e) },
      uMid: { value: new THREE.Color(0x5b3766) },
      uHorizon: { value: new THREE.Color(0xff9f70) },
      uSunDir: { value: sunDir.clone().normalize() },
    },
    vertexShader: `
      varying vec3 vDir;
      void main() {
        vDir = normalize(position);
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: `
      uniform vec3 uTop; uniform vec3 uMid; uniform vec3 uHorizon; uniform vec3 uSunDir;
      varying vec3 vDir;
      void main() {
        float h = clamp(vDir.y * 1.25 + 0.05, 0.0, 1.0);
        vec3 col = mix(uHorizon, uMid, smoothstep(0.0, 0.23, h));
        col = mix(col, uTop, smoothstep(0.18, 0.85, h));
        float sun = max(dot(normalize(vDir), normalize(uSunDir)), 0.0);
        col += vec3(1.0, 0.48, 0.18) * pow(sun, 7.0) * 0.55 * smoothstep(0.0, 0.28, h);
        col += vec3(1.0, 0.7, 0.35) * pow(sun, 40.0) * 0.15;
        float band = smoothstep(0.02, 0.06, h) * (1.0 - smoothstep(0.08, 0.2, h));
        col += vec3(0.45, 0.12, 0.18) * band * 0.18;
        gl_FragColor = vec4(col, 1.0);
      }
    `,
  })
  const sky = new THREE.Mesh(skyGeo, skyMat)
  sky.renderOrder = -100
  scene.add(sky)

  const sunPos = sunDir.clone().normalize().multiplyScalar(680)
  const glowTex = glowTexture('rgba(255,236,198,1)')
  addGlow(scene, glowTex, 0xffb070, 300, sunPos, 0.3)
  addGlow(scene, glowTex, 0xffd9a0, 150, sunPos, 0.48)
  const disc = new THREE.Mesh(
    new THREE.CircleGeometry(17, 28),
    new THREE.MeshBasicMaterial({ color: 0xffe9c4, fog: false, toneMapped: false, transparent: true, opacity: 0.95 }),
  )
  disc.position.copy(sunPos).multiplyScalar(0.97)
  disc.lookAt(0, 0, 0)
  scene.add(disc)

  const cloudTex = makeCloudTexture()
  for (let i = 0; i < 9; i++) {
    const mat = new THREE.SpriteMaterial({
      map: cloudTex, color: i % 2 ? 0xffb0a0 : 0xc4a5d8,
      transparent: true, opacity: 0.28 + Math.random() * 0.16, depthWrite: false, fog: false, toneMapped: false,
    })
    const s = new THREE.Sprite(mat)
    const a = Math.PI * (0.4 + Math.random() * 1.2)
    s.position.set(Math.cos(a) * 620, 70 + Math.random() * 100, Math.sin(a) * -620)
    const w = 190 + Math.random() * 240
    s.scale.set(w, w * 0.36, 1)
    scene.add(s)
  }

  return { sky, sunPos }
}

/* ------------------------------------------------------------------- hills */

function createHills(scene, rng) {
  const group = new THREE.Group()
  const mats = [0x3d4a42, 0x4c5043, 0x323d3d, 0x5b5647].map(
    (c) => new THREE.MeshStandardMaterial({ color: c, roughness: 0.95, metalness: 0, flatShading: true }),
  )
  const geos = []
  for (let i = 0; i < 9; i++) {
    const geo = new THREE.ConeGeometry(1, 1, 8, 3)
    geos.push(geo)
    const mesh = new THREE.Mesh(geo, mats[i % mats.length])
    const x = -260 + i * 62 + rng.range(-20, 20)
    const h = 34 + rng.range(0, 58)
    mesh.scale.set(95 + rng.range(0, 50), h, 70 + rng.range(0, 30))
    mesh.position.set(x, h / 2 - 4, -275 - rng.range(0, 50))
    mesh.rotation.y = rng.range(0, Math.PI)
    group.add(mesh)
  }
  // low ridge in front of the mountains
  for (let i = 0; i < 7; i++) {
    const mesh = new THREE.Mesh(geos[0], mats[(i + 1) % mats.length])
    const h = 16 + rng.range(0, 20)
    mesh.scale.set(70 + rng.range(0, 40), h, 60 + rng.range(0, 20))
    mesh.position.set(-220 + i * 74, h / 2 - 3, -205 - rng.range(0, 20))
    mesh.rotation.y = rng.range(0, Math.PI)
    group.add(mesh)
  }
  scene.add(group)

  // SAN ANDREAS hillside sign
  const { c, ctx } = canvas2d(1280, 220)
  ctx.clearRect(0, 0, 1280, 220)
  ctx.textAlign = 'center'
  ctx.textBaseline = 'middle'
  ctx.font = '900 150px "Arial Black", Arial, sans-serif'
  ctx.shadowColor = '#ffcf9a'
  ctx.shadowBlur = 30
  ctx.fillStyle = '#f7ecd9'
  ctx.fillText('SAN ANDREAS', 640, 112)
  ctx.shadowBlur = 0
  const tex = canvasTexture(c)
  const signMat = new THREE.MeshBasicMaterial({ map: tex, transparent: true, toneMapped: false, fog: false, side: THREE.DoubleSide })
  const sign = new THREE.Mesh(new THREE.PlaneGeometry(150, 25.8), signMat)
  sign.position.set(-10, 42, -236)
  scene.add(sign)
  const poleMat = new THREE.MeshStandardMaterial({ color: 0x211d24, roughness: 0.85 })
  for (const x of [-58, -20, 20, 58]) {
    const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.45, 0.7, 24, 6), poleMat)
    pole.position.set(x, 27, -237)
    scene.add(pole)
  }
  const backGlow = new THREE.PointLight(0xff9d63, 250, 90, 2)
  backGlow.position.set(0, 36, -238)
  scene.add(backGlow)
}

/* --------------------------------------------------------------- palm trees */

function palmCrownGeometry() {
  const leaves = []
  for (let i = 0; i < 11; i++) {
    const angle = (i / 11) * Math.PI * 2 + Math.random() * 0.22
    const len = 2.7 + Math.random() * 1.2
    const droop = 0.85 + Math.random() * 0.55
    const positions = []
    const indices = []
    const segs = 6
    for (let s = 0; s <= segs; s++) {
      const t = s / segs
      const halfW = 0.32 * (1 - t) * (0.4 + Math.sin(t * Math.PI) * 0.9)
      const x = t * len
      const y = Math.sin(t * 2.1) * 0.18 - t * t * droop
      positions.push(x, y, -halfW, x, y, halfW)
      if (s < segs) {
        const a = s * 2
        indices.push(a, a + 1, a + 2, a + 1, a + 3, a + 2)
      }
    }
    const g = new THREE.BufferGeometry()
    g.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3))
    g.setIndex(indices)
    g.computeVertexNormals()
    g.rotateY(angle)
    leaves.push(g)
  }
  return mergeGeometries(leaves)
}

function createPalms(scene, spots, share) {
  const leafMat = new THREE.MeshStandardMaterial({ color: 0x2a5b3e, roughness: 0.88, side: THREE.DoubleSide, metalness: 0.02 })
  const leafMat2 = new THREE.MeshStandardMaterial({ color: 0x3a6e46, roughness: 0.9, side: THREE.DoubleSide, metalness: 0.02 })
  const trunkMat = new THREE.MeshStandardMaterial({ color: 0x6a4a32, roughness: 0.95 })
  const crownGeo = palmCrownGeometry()
  const trunkGeo = new THREE.CylinderGeometry(0.15, 0.32, 5.6, 7, 4)
  const palms = []
  for (const [x, z, scale = 1] of spots) {
    const group = new THREE.Group()
    const trunk = new THREE.Mesh(trunkGeo, trunkMat)
    trunk.position.y = 2.8
    trunk.rotation.z = (Math.random() - 0.5) * 0.08
    group.add(trunk)
    const crown = new THREE.Mesh(crownGeo, Math.random() > 0.45 ? leafMat : leafMat2)
    crown.position.y = 5.6
    crown.rotation.y = Math.random() * Math.PI * 2
    group.add(crown)
    const shadow = groundGlow(glowTexture('rgba(0,0,0,1)'), 0x000000, 5.5, 0.28)
    shadow.material.blending = THREE.NormalBlending
    shadow.position.y = 0.035
    group.add(shadow)
    group.position.set(x, 0, z)
    group.scale.setScalar(scale)
    group.rotation.y = Math.random() * Math.PI * 2
    scene.add(group)
    palms.push(group)
  }
  return palms
}

/* -------------------------------------------------------------- buildings */

function createBuildings(scene, rng, blockTypes) {
  const colliders = []
  const landmarks = []
  const facadeVariants = []
  for (let i = 0; i < 6; i++) facadeVariants.push(facadeTextures(i, 100 + i * 31))
  const facadeCache = new Map()
  const roofMats = [0x6f6a70, 0x5d5a64, 0x79706b, 0x4c4a58].map(
    (c) => new THREE.MeshStandardMaterial({ color: c, roughness: 0.92, metalness: 0.06 }),
  )
  const trimMat = new THREE.MeshStandardMaterial({ color: 0x9a918c, roughness: 0.82 })
  const darkGlass = new THREE.MeshStandardMaterial({ color: 0x101624, roughness: 0.2, metalness: 0.75 })

  function materialFor(variant, w, h) {
    const key = `${variant}:${Math.round(w / 8)}:${Math.round(h / 10)}`
    if (facadeCache.has(key)) return facadeCache.get(key)
    const base = facadeVariants[variant]
    const map = base.map.clone()
    map.needsUpdate = true
    map.wrapS = map.wrapT = THREE.RepeatWrapping
    map.repeat.set(Math.max(1, Math.round(w / 13)), Math.max(1, Math.round(h / 14)))
    const em = base.emissiveMap.clone()
    em.needsUpdate = true
    em.wrapS = em.wrapT = THREE.RepeatWrapping
    em.repeat.copy(map.repeat)
    const mat = new THREE.MeshStandardMaterial({
      map, emissiveMap: em, emissive: 0xffffff, emissiveIntensity: 0.7,
      roughness: 0.82, metalness: 0.05,
    })
    facadeCache.set(key, mat)
    return mat
  }

  function addTower(cx, cz, w, d, h, variant, opts = {}) {
    const mat = materialFor(variant, w, h)
    const roof = roofMats[Math.floor(rng.next() * roofMats.length)]
    const geo = new THREE.BoxGeometry(w, h, d)
    const mesh = new THREE.Mesh(geo, [mat, mat, roof, roof, mat, mat])
    mesh.position.set(cx, 0.18 + h / 2, cz)
    scene.add(mesh)
    colliders.push({ minX: cx - w / 2, maxX: cx + w / 2, minZ: cz - d / 2, maxZ: cz + d / 2, h })

    // roof lip
    const lip = new THREE.Mesh(new THREE.BoxGeometry(w + 0.55, 0.45, d + 0.55), trimMat)
    lip.position.set(cx, 0.18 + h + 0.2, cz)
    scene.add(lip)

    // rooftop units
    const units = rng.int(1, 3)
    for (let i = 0; i < units; i++) {
      const uw = rng.range(1.2, Math.min(4.4, w * 0.25))
      const ud = rng.range(1.2, Math.min(3.6, d * 0.25))
      const uh = rng.range(0.5, 1.8)
      const unit = new THREE.Mesh(new THREE.BoxGeometry(uw, uh, ud), darkGlass)
      unit.position.set(cx + rng.range(-w * 0.28, w * 0.28), 0.18 + h + 0.4 + uh / 2, cz + rng.range(-d * 0.28, d * 0.28))
      scene.add(unit)
    }

    // corner neon accent
    if (opts.neon || rng.chance(0.4)) {
      const color = facadeVariants[variant].accent
      const matNeon = new THREE.MeshBasicMaterial({ color, toneMapped: false })
      const strip = new THREE.Mesh(new THREE.BoxGeometry(0.09, h * 0.88, 0.09), matNeon)
      const sx = rng.chance(0.5) ? -1 : 1
      const sz = rng.chance(0.5) ? -1 : 1
      strip.position.set(cx + sx * (w / 2 + 0.02), 0.18 + h * 0.47, cz + sz * (d / 2 + 0.02))
      scene.add(strip)
      if (rng.chance(0.3)) {
        const strip2 = strip.clone()
        strip2.position.x = cx - sx * (w / 2 + 0.02)
        scene.add(strip2)
      }
    }

    // ground-floor storefront band
    if (h > 13 && opts.store !== false) {
      const bandH = 3.1
      const band = new THREE.Mesh(new THREE.BoxGeometry(w + 0.16, bandH, d + 0.16), darkGlass)
      band.position.set(cx, 0.18 + bandH / 2, cz)
      scene.add(band)
      const bandGlow = new THREE.Mesh(
        new THREE.BoxGeometry(w * 0.72, 0.12, 0.12),
        new THREE.MeshBasicMaterial({ color: rng.chance(0.5) ? 0xffd18a : 0x8ff4ff, toneMapped: false }),
      )
      bandGlow.position.set(cx, 0.18 + 2.85, cz + d / 2 + 0.09)
      scene.add(bandGlow)
    }

    // antenna
    if (h > 46 && rng.chance(0.55)) {
      const mast = new THREE.Mesh(new THREE.CylinderGeometry(0.09, 0.18, 8, 5), darkGlass)
      mast.position.set(cx, 0.18 + h + 4.4, cz)
      scene.add(mast)
      const beacon = new THREE.Mesh(new THREE.SphereGeometry(0.28, 8, 6), new THREE.MeshBasicMaterial({ color: 0xff3040, toneMapped: false }))
      beacon.position.set(cx, 0.18 + h + 8.4, cz)
      scene.add(beacon)
    }

    landmarks.push({ x: cx, z: cz, w, d, h, variant, accent: facadeVariants[variant].accent })
    return mesh
  }

  const billboards = [
    { lines: ['VOLT', 'THE FUTURE IS ELECTRIC', 'NEON MOTORS'], colors: ['#66f4ff', '#ff2e7e'] },
    { lines: ['NEON STATE', '2026', 'SAN ANDREAS'], colors: ['#ff7cb1', '#ffc857'] },
    { lines: ['APEX', 'JOIN THE PATROL', 'LSPD'], colors: ['#64a8ff', '#ffffff'] },
    { lines: ['LUMEN', 'CITY PROOF', 'KITE MOBILITY'], colors: ['#ff7cf0', '#66f4ff'] },
  ]

  let bi = 0
  for (const block of blockTypes) {
    if (block.type !== 'buildings') continue
    const { x, z, i, j } = block
    const downtown = j <= 1
    const variant = Math.floor(rng.next() * 6)
    const tallBias = downtown ? 1.7 : 1
    const layout = rng.int(0, 2)
    if (block.landmark) {
      // signature stepped tower
      addTower(x, z, 22, 22, 62, 3, { neon: true })
      addTower(x, z, 16, 16, 86, 3, { neon: true, store: false })
      addTower(x, z, 8, 8, 96, 3, { neon: true, store: false })
      const spire = new THREE.Mesh(new THREE.CylinderGeometry(0.12, 0.4, 18, 6), darkGlass)
      spire.position.set(x, 0.18 + 96 + 9, z)
      scene.add(spire)
      const beacon = new THREE.Mesh(new THREE.SphereGeometry(0.5, 8, 6), new THREE.MeshBasicMaterial({ color: 0xff4f72, toneMapped: false }))
      beacon.position.set(x, 0.18 + 96 + 18, z)
      scene.add(beacon)
      landmarks.push({ x, z, w: 22, d: 22, h: 96, variant: 3, accent: '#c4d4ff' })
      continue
    }
    if (layout === 0) {
      const w = rng.range(17, 25)
      const d = rng.range(17, 24)
      const h = clamp(rng.range(13, 34) * tallBias, 10, 62)
      const ox = rng.range(-(40 - w) / 2 + 1, (40 - w) / 2 - 1)
      const oz = rng.range(-(40 - d) / 2 + 1, (40 - d) / 2 - 1)
      addTower(x + ox, z + oz, w, d, h, variant)
    } else if (layout === 1) {
      const h1 = clamp(rng.range(20, 44) * tallBias, 15, 72)
      addTower(x - 8.5, z - 7, 18, 17, h1, variant)
      const w2 = rng.range(11, 15)
      const d2 = rng.range(11, 15)
      addTower(x + 9, z + 9.5, w2, d2, clamp(rng.range(9, 24), 8, 38), (variant + 2) % 6)
    } else {
      const w = rng.range(22, 28)
      const d = rng.range(20, 26)
      const podH = rng.range(5.2, 9)
      const towerW = w * rng.range(0.52, 0.7)
      const towerD = d * rng.range(0.5, 0.68)
      const h = clamp(rng.range(26, 54) * tallBias, 18, 78)
      addTower(x, z, w, d, podH, (variant + 1) % 6, { store: false, neon: false })
      addTower(x + rng.range(-1.5, 1.5), z + rng.range(-1.5, 1.5), towerW, towerD, h, variant)
    }

    // billboard on a random building in this block
    if (bi < billboards.length && rng.chance(0.55) && (i + j) % 2 === 0) {
      const bb = billboards[bi++]
      const tex = billboardTextureFor(bb)
      const w = 13
      const h = 8
      const board = new THREE.Mesh(
        new THREE.PlaneGeometry(w, h),
        new THREE.MeshBasicMaterial({ map: tex, toneMapped: false, side: THREE.DoubleSide }),
      )
      board.position.set(x + rng.range(-8, 8), 13 + rng.range(0, 8), z + 21.2)
      board.rotation.y = Math.PI
      scene.add(board)
      const frame = new THREE.Mesh(new THREE.BoxGeometry(w + 0.6, h + 0.6, 0.4), darkTrim())
      frame.position.copy(board.position)
      frame.position.z -= 0.22
      frame.rotation.y = Math.PI
      scene.add(frame)
      const glow = new THREE.PointLight(0xff7cb1, 22, 26, 2)
      glow.position.set(board.position.x, board.position.y, board.position.z + 5)
      scene.add(glow)
    }
  }

  function darkTrim() {
    return new THREE.MeshStandardMaterial({ color: 0x17161f, roughness: 0.8 })
  }

  function billboardTextureFor(bb) {
    return billboardTex(bb.lines, bb.colors)
  }

  return { colliders, landmarks }
}

let _billboardTexFn = null
function billboardTex(lines, colors) {
  if (!_billboardTexFn) _billboardTexFn = billboardsImport
  return _billboardTexFn(lines, colors)
}

// small indirection keeps module imports tidy
function billboardsImport(lines, colors) {
  // implemented via signTexture-style canvas for a glossy digital billboard
  const { c, ctx } = canvas2d(512, 320)
  const grad = ctx.createLinearGradient(0, 0, 512, 320)
  grad.addColorStop(0, '#100b22')
  grad.addColorStop(0.55, '#1b1030')
  grad.addColorStop(1, '#2a0e2c')
  ctx.fillStyle = grad
  ctx.fillRect(0, 0, 512, 320)
  ctx.strokeStyle = colors[1]
  ctx.lineWidth = 5
  ctx.strokeRect(14, 14, 484, 292)
  ctx.textAlign = 'center'
  ctx.fillStyle = '#fff'
  ctx.shadowColor = colors[0]
  ctx.shadowBlur = 26
  ctx.font = '900 78px "Arial Black", Arial, sans-serif'
  ctx.fillText(lines[0], 256, 140)
  ctx.shadowBlur = 0
  ctx.fillStyle = colors[0]
  ctx.font = '800 30px Arial, sans-serif'
  ctx.fillText(lines[1], 256, 208)
  ctx.fillStyle = 'rgba(255,255,255,0.6)'
  ctx.font = '800 18px Arial, sans-serif'
  ctx.fillText(lines[2], 256, 260)
  for (let i = 0; i < 30; i++) {
    ctx.fillStyle = `rgba(255,255,255,${Math.random() * 0.04})`
    ctx.fillRect(14, 14 + Math.random() * 292, 484, 2)
  }
  return canvasTexture(c)
}

