/* ------------------------------------------------------------------- roads */

function createRoadMarkings(scene) {
  const dashGeo = new THREE.BoxGeometry(3.2, 0.02, 0.17)
  const dashMat = new THREE.MeshStandardMaterial({ color: 0xe7e2d2, roughness: 0.72, metalness: 0.05 })
  const items = []
  for (const road of CITY.roadCenters) {
    for (const side of [-1, 1]) {
      for (let x = CITY.min + 6; x < CITY.max - 4; x += 8) {
        items.push({ x, z: road + side * 4.1, rot: 0 })
      }
      for (let z = CITY.min + 6; z < CITY.max - 4; z += 8) {
        items.push({ x: road + side * 4.1, z, rot: Math.PI / 2 })
      }
    }
  }
  const inst = new THREE.InstancedMesh(dashGeo, dashMat, items.length)
  const m = new THREE.Matrix4()
  const q = new THREE.Quaternion()
  const s = new THREE.Vector3(1, 1, 1)
  items.forEach((it, i) => {
    q.setFromAxisAngle(new THREE.Vector3(0, 1, 0), it.rot)
    m.compose(new THREE.Vector3(it.x, 0.028, it.z), q, s)
    inst.setMatrixAt(i, m)
  })
  inst.instanceMatrix.needsUpdate = true
  scene.add(inst)

  // double yellow center lines
  const yellowMat = new THREE.MeshBasicMaterial({ color: 0xcda24b })
  for (const road of CITY.roadCenters) {
    for (const off of [-0.18, 0.18]) {
      const hLine = new THREE.Mesh(new THREE.BoxGeometry(CITY.max - CITY.min - 8, 0.02, 0.1), yellowMat)
      hLine.position.set(0, 0.026, road + off)
      scene.add(hLine)
      const vLine = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.02, CITY.max - CITY.min - 8), yellowMat)
      vLine.position.set(road + off, 0.026, 0)
      scene.add(vLine)
    }
  }

  // crosswalks at the central intersections
  const whiteMat = new THREE.MeshStandardMaterial({ color: 0xe4dfd2, roughness: 0.8 })
  const stripes = []
  const intersections = [CITY.roadCenters[2], CITY.roadCenters[3], CITY.roadCenters[4]]
  for (const x of intersections) {
    for (const z of intersections) {
      for (let i = -3; i <= 3; i++) {
        stripes.push({ x: x + i * 1.35, z: z + 7.2, rot: 0 })
        stripes.push({ x: x + i * 1.35, z: z - 7.2, rot: 0 })
        stripes.push({ x: x + 7.2, z: z + i * 1.35, rot: Math.PI / 2 })
        stripes.push({ x: x - 7.2, z: z + i * 1.35, rot: Math.PI / 2 })
      }
    }
  }
  const stripeGeo = new THREE.BoxGeometry(0.74, 0.02, 3.2)
  const stripeInst = new THREE.InstancedMesh(stripeGeo, whiteMat, stripes.length)
  stripes.forEach((it, i) => {
    q.setFromAxisAngle(new THREE.Vector3(0, 1, 0), it.rot)
    m.compose(new THREE.Vector3(it.x, 0.03, it.z), q, s)
    stripeInst.setMatrixAt(i, m)
  })
  stripeInst.instanceMatrix.needsUpdate = true
  scene.add(stripeInst)
}

/* -------------------------------------------------------------------- water */

function createWater(scene) {
  const geo = new THREE.PlaneGeometry(1600, 1200, 70, 50)
  const mat = new THREE.ShaderMaterial({
    transparent: false,
    uniforms: { uTime: { value: 0 } },
    vertexShader: `
      uniform float uTime;
      varying vec2 vUv;
      varying vec3 vW;
      void main() {
        vUv = uv;
        vec3 p = position;
        p.z += sin(p.x * 0.09 + uTime * 1.2) * 0.35 + cos(p.y * 0.13 - uTime * 0.8) * 0.22;
        vec4 wp = modelMatrix * vec4(p, 1.0);
        vW = wp.xyz;
        gl_Position = projectionMatrix * viewMatrix * wp;
      }
    `,
    fragmentShader: `
      uniform float uTime;
      varying vec2 vUv;
      varying vec3 vW;
      void main() {
        float depth = 1.0 - vUv.y;
        vec3 shore = vec3(0.20, 0.52, 0.57);
        vec3 mid = vec3(0.10, 0.22, 0.35);
        vec3 far = vec3(0.20, 0.16, 0.28);
        vec3 col = mix(shore, mid, smoothstep(0.0, 0.35, depth));
        col = mix(col, far, smoothstep(0.35, 1.0, depth));
        float wave = sin(vW.x * 0.16 + uTime * 1.1) * sin(vW.z * 0.22 - uTime * 0.7);
        float glitter = pow(max(0.0, wave), 12.0);
        col += vec3(1.0, 0.65, 0.36) * glitter * 0.35 * (1.0 - smoothstep(0.0, 0.7, depth));
        float sunStreak = smoothstep(0.72, 1.0, sin(vW.x * 0.03 + 1.2)) * (1.0 - smoothstep(0.0, 0.55, depth));
        col += vec3(1.0, 0.5, 0.22) * sunStreak * 0.12;
        float foam = smoothstep(0.03, 0.0, depth) * (0.55 + 0.45 * sin(vW.x * 0.5 + uTime * 2.0));
        col = mix(col, vec3(0.85, 0.93, 0.94), foam * 0.55);
        gl_FragColor = vec4(col, 1.0);
      }
    `,
  })
  const water = new THREE.Mesh(geo, mat)
  water.rotation.x = -Math.PI / 2
  water.position.set(0, -0.12, 830)
  scene.add(water)
  return mat
}

/* ------------------------------------------------------------------- world */

export function createWorld(scene, renderer) {
  const rng = makeRng(20261031)
  const colliders = []
  const palms = []

  scene.fog = new THREE.Fog(PALETTE.fog, 105, 640)
  scene.background = new THREE.Color(0x1b1730)

  const hemi = new THREE.HemisphereLight(0x9a9bff, 0x3d2b2d, 1.15)
  scene.add(hemi)
  const sunDir = new THREE.Vector3(-0.62, 0.24, -0.75)
  const sun = new THREE.DirectionalLight(0xffb27c, 2.9)
  sun.position.copy(sunDir).multiplyScalar(300)
  scene.add(sun)
  const fill = new THREE.DirectionalLight(0x6f7dff, 0.65)
  fill.position.set(80, 45, 140)
  scene.add(fill)
  const ambient = new THREE.AmbientLight(0x2a2140, 0.9)
  scene.add(ambient)

  createSky(scene, sunDir)
  createHills(scene, rng)

  // island / city floor
  const base = new THREE.Mesh(
    new THREE.PlaneGeometry(700, 700),
    new THREE.MeshStandardMaterial({ color: 0x574c45, roughness: 1 }),
  )
  base.rotation.x = -Math.PI / 2
  base.position.y = -0.06
  scene.add(base)

  const asphalt = new THREE.Mesh(
    new THREE.PlaneGeometry(CITY.max - CITY.min + 22, CITY.max - CITY.min + 22),
    new THREE.MeshStandardMaterial({ map: asphaltTexture(), roughness: 0.93, metalness: 0.02, color: 0xa9a9b8 }),
  )
  asphalt.rotation.x = -Math.PI / 2
  asphalt.position.y = 0
  scene.add(asphalt)

  // block classification
  const blockTypes = []
  for (let i = 0; i < CITY.n; i++) {
    for (let j = 0; j < CITY.n; j++) {
      const x = CITY.blockCenters[i]
      const z = CITY.blockCenters[j]
      let type = 'buildings'
      if (i === 2 && j === 3) type = 'plaza'
      else if (i === 1 && j === 2) type = 'park'
      else if (i === 3 && j === 3) type = 'parking'
      else if (i === 2 && j === 0) type = 'landmark'
      else if (rng.chance(0.08)) type = 'park'
      blockTypes.push({ i, j, x, z, type, landmark: type === 'landmark' })
    }
  }

  const sidewalkTex = sidewalkTexture()
  const grassTex = grassTexture()
  const curbMat = new THREE.MeshStandardMaterial({ color: 0x817a72, roughness: 0.9 })
  const parkMat = new THREE.MeshStandardMaterial({ map: grassTex, roughness: 0.95 })

  for (const b of blockTypes) {
    const walk = new THREE.Mesh(new THREE.BoxGeometry(CITY.blockSize, 0.18, CITY.blockSize), new THREE.MeshStandardMaterial({ map: sidewalkTex, roughness: 0.9, color: 0xe4ded2 }))
    walk.position.set(b.x, 0.09, b.z)
    scene.add(walk)
    if (b.type === 'park') {
      const grass = new THREE.Mesh(new THREE.PlaneGeometry(39, 39), parkMat)
      grass.rotation.x = -Math.PI / 2
      grass.position.set(b.x, 0.2, b.z)
      scene.add(grass)
      // paths
      const pathMat = new THREE.MeshStandardMaterial({ color: 0xb7a58c, roughness: 0.9 })
      for (const rot of [0, Math.PI / 2]) {
        const path = new THREE.Mesh(new THREE.PlaneGeometry(39, 3.2), pathMat)
        path.rotation.x = -Math.PI / 2
        path.rotation.z = rot
        path.position.set(b.x, 0.205, b.z)
        scene.add(path)
      }
      // fountain
      const basin = new THREE.Mesh(new THREE.CylinderGeometry(5, 5.3, 0.7, 24), curbMat)
      basin.position.set(b.x, 0.55, b.z)
      scene.add(basin)
      const water = new THREE.Mesh(
        new THREE.CylinderGeometry(4.5, 4.5, 0.15, 24),
        new THREE.MeshBasicMaterial({ color: 0x56c9d6, transparent: true, opacity: 0.75 }),
      )
      water.position.set(b.x, 0.92, b.z)
      scene.add(water)
      const column = new THREE.Mesh(new THREE.CylinderGeometry(0.5, 0.8, 3.6, 12), curbMat)
      column.position.set(b.x, 2.5, b.z)
      scene.add(column)
      const bowl = new THREE.Mesh(new THREE.CylinderGeometry(2.4, 1.6, 0.5, 18), curbMat)
      bowl.position.set(b.x, 4.2, b.z)
      scene.add(bowl)
      for (let k = 0; k < 5; k++) {
        palms.push([b.x - 14 + k * 7, b.z + (k % 2 ? 15 : -15), 0.75 + rng.range(0, 0.2)])
      }
    }
    if (b.type === 'parking') {
      const lot = new THREE.Mesh(
        new THREE.PlaneGeometry(39, 39),
        new THREE.MeshStandardMaterial({ color: 0x23242e, roughness: 0.9 }),
      )
      lot.rotation.x = -Math.PI / 2
      lot.position.set(b.x, 0.19, b.z)
      scene.add(lot)
      const lineMat = new THREE.MeshBasicMaterial({ color: 0xc9c4b8 })
      for (let k = -3; k <= 3; k++) {
        const line = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.01, 9), lineMat)
        line.position.set(b.x + k * 4.4, 0.2, b.z - 10)
        scene.add(line)
        const line2 = line.clone()
        line2.position.z = b.z + 10
        scene.add(line2)
      }
    }
    // curb outline
    const curb = new THREE.Mesh(new THREE.BoxGeometry(CITY.blockSize + 0.4, 0.24, CITY.blockSize + 0.4), curbMat)
    curb.position.set(b.x, 0.12, b.z)
    scene.add(curb)
    walk.position.y = 0.2
    walk.scale.set(0.995, 1, 0.995)
  }

  // remove the block center plaza collider issues by adding showroom last
  createShowroom(scene, colliders)
  const buildingData = createBuildings(scene, rng, blockTypes)
  colliders.push(...buildingData.colliders)

  // sidewalk palms
  for (const b of blockTypes) {
    if (b.type === 'buildings' || b.type === 'landmark') {
      for (const [dx, dz] of [[-21, -21], [21, -21], [-21, 21], [21, 21]]) {
        if (rng.chance(0.46)) palms.push([b.x + dx, b.z + dz, 0.85 + rng.range(0, 0.35)])
      }
    }
    if (b.type === 'plaza') {
      for (const [dx, dz] of [[-21, -16], [21, -16], [-21, 5], [21, 5], [-18, 23], [18, 23]]) palms.push([b.x + dx, b.z + dz, 0.95])
    }
    if (b.type === 'parking') {
      for (const [dx, dz] of [[-17, 17], [17, 17]]) palms.push([b.x + dx, b.z + dz, 1.05])
    }
  }
  // boulevard and beach palms
  for (let i = 0; i < 12; i++) {
    palms.push([-150 + i * 27 + rng.range(-3, 3), 164 + rng.range(-1, 2), 1 + rng.range(0, 0.4)])
  }
  for (let i = 0; i < 14; i++) {
    palms.push([-240 + i * 36, 182 + rng.range(-4, 10), 0.9 + rng.range(0, 0.5)])
  }
  for (let i = 0; i < 8; i++) {
    palms.push([-166 + rng.range(-2, 2), -120 + i * 32, 0.9 + rng.range(0, 0.3)])
  }
  createPalms(scene, palms.filter((p) => Math.abs(p[0]) < 260), null)

  createRoadMarkings(scene)
  createLamps(scene)
  createTrafficLights(scene)
  createBeach(scene, rng)
  const waterMat = createWater(scene)

  // ambient dust motes
  const dustGeo = new THREE.BufferGeometry()
  const dustPos = new Float32Array(420 * 3)
  for (let i = 0; i < 420; i++) {
    dustPos[i * 3] = rng.range(-150, 150)
    dustPos[i * 3 + 1] = rng.range(1, 26)
    dustPos[i * 3 + 2] = rng.range(-150, 170)
  }
  dustGeo.setAttribute('position', new THREE.BufferAttribute(dustPos, 3))
  const dust = new THREE.Points(
    dustGeo,
    new THREE.PointsMaterial({ color: 0xffd8a8, size: 0.09, transparent: true, opacity: 0.45, depthWrite: false, blending: THREE.AdditiveBlending }),
  )
  scene.add(dust)

  const starTex = makeStarTexture()
  for (let i = 0; i < 26; i++) {
    const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: starTex, color: 0xfff1d0, transparent: true, opacity: 0.55, depthWrite: false, toneMapped: false, fog: false }))
    const x = rng.range(-260, 260)
    const z = rng.range(176, 240)
    s.position.set(x, rng.range(16, 30), z)
    s.scale.setScalar(rng.range(0.35, 0.7))
    scene.add(s)
  }

  return {
    colliders,
    palms,
    blockTypes,
    landmarks: buildingData.landmarks,
    showcase: {
      x: 0,
      z: 58,
      heading: Math.PI, // cars face south (+z) because our model front is +z; heading 0 = +z
    },
    spawn: { x: 0, z: 70.5, heading: Math.PI },
    missionSpots: [
      new THREE.Vector3(-32, 0, -22),
      new THREE.Vector3(96, 0, 94),
      new THREE.Vector3(-128, 0, -30),
      new THREE.Vector3(30, 0, 130),
      new THREE.Vector3(-96, 0, 64),
      new THREE.Vector3(160, 0, -96),
      new THREE.Vector3(32, 0, -128),
    ],
    shardSpots: [
      new THREE.Vector3(-10, 0.6, 82),
      new THREE.Vector3(-64, 0.6, 0),
      new THREE.Vector3(78, 0.6, 40),
      new THREE.Vector3(30, 0.6, -64),
      new THREE.Vector3(-96, 0.6, 112),
      new THREE.Vector3(128, 0.6, 128),
      new THREE.Vector3(-64, 0.6, -128),
      new THREE.Vector3(140, 0.6, 190),
      new THREE.Vector3(-120, 0.6, 196),
      new THREE.Vector3(40, 0.6, 96),
    ],
    update(dt, t) {
      waterMat.uniforms.uTime.value = t
      dust.position.y = Math.sin(t * 0.12) * 0.4
      dust.rotation.y = t * 0.004
      for (let i = 0; i < palms.length; i++) {
        const p = palms[i]
        if (p) p.rotation.z = Math.sin(t * 0.7 + i) * 0.008
      }
    },
  }
}

// Procedural soundscape: synthwave radio, electric drivetrain, impacts and UI cues.
const NOTE = (n) => 440 * Math.pow(2, (n - 69) / 12)

export class GameAudio {
  constructor() {
    this.ctx = null
    this.muted = false
    this.started = false
    this.driving = false
    this.sirenOn = false
    this.nextNoteTime = 0
    this.step = 0
    this.timer = null
    this.tempo = 94
    this.speed = 0
    this.throttle = 0
  }

  init() {
    if (this.ctx) return
    try {
      const AC = window.AudioContext || window.webkitAudioContext
      if (!AC) return
      this.ctx = new AC()
      const ctx = this.ctx
      this.master = ctx.createGain()
      this.master.gain.value = 0.62
      this.compressor = ctx.createDynamicsCompressor()
      this.compressor.threshold.value = -18
      this.compressor.knee.value = 22
      this.compressor.ratio.value = 6
      this.master.connect(this.compressor)
      this.compressor.connect(ctx.destination)

      this.musicGain = ctx.createGain()
      this.musicGain.gain.value = 0.22
      this.musicGain.connect(this.master)

      this.sfxGain = ctx.createGain()
      this.sfxGain.gain.value = 0.5
      this.sfxGain.connect(this.master)

      this.engineGain = ctx.createGain()
      this.engineGain.gain.value = 0
      this.engineGain.connect(this.master)

      // delay send for arpeggios
      this.delay = ctx.createDelay(1.0)
      this.delay.delayTime.value = 0.34
      this.delayFeedback = ctx.createGain()
      this.delayFeedback.gain.value = 0.34
      this.delay.connect(this.delayFeedback)
      this.delayFeedback.connect(this.delay)
      const wet = ctx.createGain()
      wet.gain.value = 0.2
      this.delay.connect(wet)
      wet.connect(this.musicGain)

      this.noiseBuffer = this.makeNoise(2)
      this.startEngine()
      this.startMusic()
      this.started = true
      this.applyMute()
      ctx.resume?.()
    } catch (err) {
      console.warn('audio unavailable', err)
    }
  }

  makeNoise(seconds = 1) {
    const ctx = this.ctx
    const buf = ctx.createBuffer(1, Math.floor(ctx.sampleRate * seconds), ctx.sampleRate)
    const data = buf.getChannelData(0)
    for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1
    return buf
  }

  /* ---------------------------------------------------------- engine + tires */

  startEngine() {
    const ctx = this.ctx
    this.engineFilter = ctx.createBiquadFilter()
    this.engineFilter.type = 'lowpass'
    this.engineFilter.frequency.value = 280
    this.engineFilter.Q.value = 2.2
    this.engineFilter.connect(this.engineGain)

    this.engineOscA = ctx.createOscillator()
    this.engineOscA.type = 'sawtooth'
    this.engineOscA.frequency.value = 42
    const gainA = ctx.createGain()
    gainA.gain.value = 0.12
    this.engineOscA.connect(gainA)
    gainA.connect(this.engineFilter)
    this.engineOscA.start()

    this.engineOscB = ctx.createOscillator()
    this.engineOscB.type = 'square'
    this.engineOscB.frequency.value = 86
    const gainB = ctx.createGain()
    gainB.gain.value = 0.035
    this.engineOscB.connect(gainB)
    gainB.connect(this.engineFilter)
    this.engineOscB.start()

    this.whine = ctx.createOscillator()
    this.whine.type = 'sine'
    this.whine.frequency.value = 640
    const whineGain = ctx.createGain()
    whineGain.gain.value = 0.025
    this.whine.connect(whineGain)
    whineGain.connect(this.engineGain)
    this.whine.start()

    const noise = ctx.createBufferSource()
    noise.buffer = this.noiseBuffer
    noise.loop = true
    this.tireFilter = ctx.createBiquadFilter()
    this.tireFilter.type = 'bandpass'
    this.tireFilter.frequency.value = 1800
    this.tireFilter.Q.value = 1.4
    this.tireGain = ctx.createGain()
    this.tireGain.gain.value = 0
    noise.connect(this.tireFilter)
    this.tireFilter.connect(this.tireGain)
    this.tireGain.connect(this.master)
    noise.start()
  }

  updateEngine({ driving, speed, throttle, braking, boosting, drifting }) {
    if (!this.ctx) return
    const t = this.ctx.currentTime
    const targetGain = driving ? 0.15 + Math.abs(throttle) * 0.12 : 0
    this.engineGain.gain.setTargetAtTime(targetGain, t, 0.08)
    const spd = Math.abs(speed)
    const base = 38 + Math.min(spd, 90) * 2.4
    this.engineOscA.frequency.setTargetAtTime(base, t, 0.05)
    this.engineOscB.frequency.setTargetAtTime(base * 2.03, t, 0.05)
    this.whine.frequency.setTargetAtTime(520 + spd * 26, t, 0.05)
    this.engineFilter.frequency.setTargetAtTime(180 + spd * 20 + Math.abs(throttle) * 140, t, 0.08)
    const tire = driving && drifting && spd > 8 ? Math.min(0.1, spd * 0.0018) : 0
    this.tireGain.gain.setTargetAtTime(tire, t, 0.06)
    this.engineGain.gain.setTargetAtTime(targetGain + (boosting ? 0.035 : 0), t, 0.08)
  }

  /* --------------------------------------------------------------- music */

  startMusic() {
    const ctx = this.ctx
    this.nextNoteTime = ctx.currentTime + 0.1
    this.timer = setInterval(() => this.scheduler(), 60)
  }

  scheduler() {
    if (!this.ctx) return
    const ahead = 0.16
    while (this.nextNoteTime < this.ctx.currentTime + ahead) {
      this.scheduleStep(this.step, this.nextNoteTime)
      this.nextNoteTime += 60 / this.tempo / 4
      this.step++
      if (this.step >= 64) this.step = 0
    }
  }

  scheduleStep(step, time) {
    const ctx = this.ctx
    const bar = Math.floor(step / 16) % 4
    const chords = [
      [57, 60, 64, 69], // Am7
      [53, 57, 60, 65], // Fmaj7
      [48, 55, 60, 64], // Cmaj7
      [55, 59, 62, 67], // G
    ]
    const roots = [33, 29, 36, 31]
    const chord = chords[bar]

    if (step % 16 === 0) {
      for (const n of chord.slice(0, 3)) {
        this.pad(NOTE(n - 12), time, 4.2, 0.024)
      }
    }
    // bass pulse
    if (step % 4 === 0) {
      this.pluck(NOTE(roots[bar]), time, 0.4, 0.07, 'sawtooth', 280)
    }
    if (step % 8 === 4) {
      this.pluck(NOTE(roots[bar] + 12), time, 0.18, 0.035, 'triangle', 420)
    }
    // arp
    if (step % 2 === 0) {
      const pattern = [0, 2, 1, 3, 2, 1, 3, 0]
      const n = chord[pattern[(step / 2) % 8]]
      this.pluck(NOTE(n + 12), time, 0.13, 0.03, 'triangle', 1800, this.delay)
    }
    // hats
    if (step % 2 === 1) this.hat(time, step % 4 === 3 ? 0.035 : 0.018)
    // kick
    if (step % 4 === 0) this.kick(time)
    // clap-ish
    if (step % 16 === 4 || step % 16 === 12) this.hat(time, 0.05, 1300)
  }

  pad(freq, time, dur, vol) {
    const ctx = this.ctx
    const osc = ctx.createOscillator()
    osc.type = 'sawtooth'
    osc.frequency.value = freq
    const filter = ctx.createBiquadFilter()
    filter.type = 'lowpass'
    filter.frequency.value = 1100
    filter.Q.value = 0.6
    const gain = ctx.createGain()
    gain.gain.setValueAtTime(0.0001, time)
    gain.gain.linearRampToValueAtTime(vol, time + 0.5)
    gain.gain.linearRampToValueAtTime(vol * 0.7, time + dur * 0.7)
    gain.gain.exponentialRampToValueAtTime(0.0001, time + dur)
    osc.connect(filter)
    filter.connect(gain)
    gain.connect(this.musicGain)
    osc.start(time)
    osc.stop(time + dur + 0.05)
  }

  pluck(freq, time, dur, vol, type = 'triangle', cutoff = 2000, destination = null) {
    const ctx = this.ctx
    const osc = ctx.createOscillator()
    osc.type = type
    osc.frequency.value = freq
    const filter = ctx.createBiquadFilter()
    filter.type = 'lowpass'
    filter.frequency.value = cutoff
    const gain = ctx.createGain()
    gain.gain.setValueAtTime(0.0001, time)
    gain.gain.linearRampToValueAtTime(vol, time + 0.008)
    gain.gain.exponentialRampToValueAtTime(0.0001, time + dur)
    osc.connect(filter)
    filter.connect(gain)
    gain.connect(this.musicGain)
    if (destination) gain.connect(destination)
    osc.start(time)
    osc.stop(time + dur + 0.02)
  }

  kick(time) {
    const ctx = this.ctx
    const osc = ctx.createOscillator()
    osc.type = 'sine'
    osc.frequency.setValueAtTime(130, time)
    osc.frequency.exponentialRampToValueAtTime(42, time + 0.14)
    const gain = ctx.createGain()
    gain.gain.setValueAtTime(0.14, time)
    gain.gain.exponentialRampToValueAtTime(0.0001, time + 0.3)
    osc.connect(gain)
    gain.connect(this.musicGain)
    osc.start(time)
    osc.stop(time + 0.32)
  }

  hat(time, vol = 0.02, cutoff = 6500) {
    const ctx = this.ctx
    const src = ctx.createBufferSource()
    src.buffer = this.noiseBuffer
    const filter = ctx.createBiquadFilter()
    filter.type = 'highpass'
    filter.frequency.value = cutoff
    const gain = ctx.createGain()
    gain.gain.setValueAtTime(vol, time)
    gain.gain.exponentialRampToValueAtTime(0.0001, time + 0.055)
    src.connect(filter)
    filter.connect(gain)
    gain.connect(this.musicGain)
    src.start(time)
    src.stop(time + 0.08)
  }

  /* ------------------------------------------------------------------ sfx */

  blip(freq = 660, dur = 0.1, vol = 0.06, type = 'sine') {
    if (!this.ctx) return
    const ctx = this.ctx
    const t = ctx.currentTime
    const osc = ctx.createOscillator()
    osc.type = type
    osc.frequency.setValueAtTime(freq, t)
    const gain = ctx.createGain()
    gain.gain.setValueAtTime(0.0001, t)
    gain.gain.linearRampToValueAtTime(vol, t + 0.01)
    gain.gain.exponentialRampToValueAtTime(0.0001, t + dur)
    osc.connect(gain)
    gain.connect(this.sfxGain)
    osc.start(t)
    osc.stop(t + dur + 0.02)
  }

  chime() {
    this.blip(880, 0.16, 0.055)
    setTimeout(() => this.blip(1320, 0.22, 0.05), 80)
  }

  cash() {
    this.blip(990, 0.09, 0.05)
    setTimeout(() => this.blip(1480, 0.13, 0.045), 65)
    setTimeout(() => this.blip(1760, 0.2, 0.04), 140)
  }

  enterCar() {
    this.blip(180, 0.2, 0.07, 'sawtooth')
    setTimeout(() => this.blip(420, 0.15, 0.04), 60)
  }

  crash(intensity = 1) {
    if (!this.ctx) return
    const ctx = this.ctx
    const t = ctx.currentTime
    const src = ctx.createBufferSource()
    src.buffer = this.noiseBuffer
    const filter = ctx.createBiquadFilter()
    filter.type = 'lowpass'
    filter.frequency.setValueAtTime(1500, t)
    filter.frequency.exponentialRampToValueAtTime(180, t + 0.3)
    const gain = ctx.createGain()
    gain.gain.setValueAtTime(0.18 * Math.min(1.6, intensity), t)
    gain.gain.exponentialRampToValueAtTime(0.0001, t + 0.4)
    src.connect(filter)
    filter.connect(gain)
    gain.connect(this.sfxGain)
    src.start(t)
    src.stop(t + 0.42)
    const osc = ctx.createOscillator()
    osc.type = 'sine'
    osc.frequency.setValueAtTime(90, t)
    osc.frequency.exponentialRampToValueAtTime(36, t + 0.25)
    const g2 = ctx.createGain()
    g2.gain.setValueAtTime(0.14, t)
    g2.gain.exponentialRampToValueAtTime(0.0001, t + 0.3)
    osc.connect(g2)
    g2.connect(this.sfxGain)
    osc.start(t)
    osc.stop(t + 0.32)
  }

  horn() {
    if (!this.ctx) return
    const ctx = this.ctx
    const t = ctx.currentTime
    for (const f of [392, 494]) {
      const osc = ctx.createOscillator()
      osc.type = 'square'
      osc.frequency.value = f
      const gain = ctx.createGain()
      gain.gain.setValueAtTime(0.0001, t)
      gain.gain.linearRampToValueAtTime(0.035, t + 0.02)
      gain.gain.setValueAtTime(0.035, t + 0.17)
      gain.gain.exponentialRampToValueAtTime(0.0001, t + 0.28)
      osc.connect(gain)
      gain.connect(this.sfxGain)
      osc.start(t)
      osc.stop(t + 0.3)
    }
  }

  setMuted(muted) {
    this.muted = muted
    this.applyMute()
  }

  applyMute() {
    if (!this.ctx) return
    this.master.gain.setTargetAtTime(this.muted ? 0 : 0.62, this.ctx.currentTime, 0.05)
  }

  setSiren(on) {
    if (!this.ctx) return
    if (on && !this.sirenOn) {
      this.sirenOn = true
      const ctx = this.ctx
      this.sirenOsc = ctx.createOscillator()
      this.sirenOsc.type = 'square'
      this.sirenOsc.frequency.value = 720
      this.sirenLfo = ctx.createOscillator()
      this.sirenLfo.type = 'sine'
      this.sirenLfo.frequency.value = 1.7
      const lfoGain = ctx.createGain()
      lfoGain.gain.value = 220
      this.sirenLfo.connect(lfoGain)
      lfoGain.connect(this.sirenOsc.frequency)
      this.sirenGain = ctx.createGain()
      this.sirenGain.gain.value = 0.018
      this.sirenOsc.connect(this.sirenGain)
      this.sirenGain.connect(this.sfxGain)
      this.sirenOsc.start()
      this.sirenLfo.start()
    } else if (!on && this.sirenOn) {
      this.sirenOn = false
      try {
        this.sirenGain.gain.setTargetAtTime(0, this.ctx.currentTime, 0.1)
        this.sirenOsc.stop(this.ctx.currentTime + 0.4)
        this.sirenLfo.stop(this.ctx.currentTime + 0.4)
      } catch {}
    }
  }

  suspend() {
    this.ctx?.suspend?.()
  }
  resume() {
    this.ctx?.resume?.()
  }
}

import { CITY } from './city.js'
import { clamp } from './utils.js'

const $ = (id) => document.getElementById(id)

const DISTRICTS = [
  { name: 'NEON DISTRICT', test: (x, z) => z > 30 && z < 150 && Math.abs(x) < 60 },
  { name: 'DOWNTOWN LOS SANTOS', test: (x, z) => z < 30 && z > -150 && x < 60 },
  { name: 'VINEWOOD HILLS', test: (x, z) => z < -100 },
  { name: 'DEL PERRO BEACH', test: (x, z) => z > 150 && z < 232 },
  { name: 'EAST LOS SANTOS', test: (x) => x > 90 },
  { name: 'WEST LOS SANTOS', test: (x) => x < -90 },
  { name: 'SAN ANDREAS FREEWAY', test: () => true },
]

export class UI {
  constructor() {
    this.el = {
      hud: $('hud'), title: $('title'), play: $('play-btn'), minimap: $('minimap'),
      cash: $('cash'), clock: $('clock'), district: $('district-name'),
      wanted: [...document.querySelectorAll('#wanted .star')],
      missionCard: $('mission-card'), missionTitle: $('mission-title'), missionTarget: $('mission-target'),
      missionTimer: $('mission-timer'), missionDistance: $('mission-distance'), missionProgress: $('mission-progress'),
      healthBar: $('health-bar'), healthValue: $('health-value'),
      armorBar: $('armor-bar'), armorValue: $('armor-value'),
      vehiclePanel: $('vehicle-panel'), vBrand: $('v-brand'), vName: $('v-name'),
      speed: $('speed'), gear: $('gear'), vClass: $('v-class'), vMode: $('v-mode'),
      batteryBar: $('battery-bar'), batteryValue: $('battery-value'),
      interact: $('interact'), interactText: $('interact-text'),
      toastStack: $('toast-stack'), vehicleCard: $('vehicle-card'),
      vcName: $('vc-name'), vcSub: $('vc-sub'), vcSpeed: $('vc-speed'), vcAccel: $('vc-accel'), vcHandling: $('vc-handling'),
      mute: $('mute-btn'), touchAction: $('touch-action'), touchGas: $('touch-gas'),
      touchBrake: $('touch-brake'), touchBoost: $('touch-boost'), touchHandbrake: $('touch-handbrake'),
      joystick: $('joystick'), stick: document.querySelector('#joystick .stick'),
      loading: $('loading'), flash: $('flash'), busted: $('busted'), wasted: $('wasted'),
      cinematic: $('cinematic'), cineTitle: $('cine-title'), cineSub: $('cine-sub'),
    }
    this.cache = {}
    this.touch = { x: 0, y: 0, gas: false, brake: false, boost: false, handbrake: false }
    this.onAction = null
    this.onMute = null
    this.onPlay = null
    this.missionDistance = 0
    this.mapCanvas = document.createElement('canvas')
    this.mapCanvas.width = 512
    this.mapCanvas.height = 512
    this.mapCtx = this.mapCanvas.getContext('2d')
    this.mapReady = false
    this.timeouts = new Set()
    this.setup()
  }

  setup() {
    document.body.classList.add('title-mode')

    this.el.play.addEventListener('click', () => {
      if (this.playing) return
      this.playing = true
      this.el.title.classList.add('gone')
      document.body.classList.remove('title-mode')
      document.body.classList.add('playing')
      this.onPlay?.()
    })

    this.el.mute.addEventListener('click', (e) => {
      e.stopPropagation()
      const muted = document.body.classList.toggle('muted')
      this.el.mute.textContent = muted ? '×' : '♪'
      this.onMute?.(muted)
    })

    const isTouch = window.matchMedia('(pointer: coarse)').matches || 'ontouchstart' in window
    this.isTouch = isTouch
    document.body.classList.toggle('touch', isTouch)
    this.setupTouch()
  }

  setupTouch() {
    const stick = this.el.stick
    const joy = this.el.joystick
    let active = null
    const setStick = (dx, dy) => {
      const max = 40
      const dist = Math.hypot(dx, dy)
      const k = dist > max ? max / dist : 1
      const x = dx * k
      const y = dy * k
      stick.style.transform = `translate(${x}px, ${y}px)`
      this.touch.x = x / max
      this.touch.y = y / max
    }
    const move = (e) => {
      if (!active) return
      const rect = joy.getBoundingClientRect()
      setStick(e.clientX - (rect.left + rect.width / 2), e.clientY - (rect.top + rect.height / 2))
    }
    const end = () => {
      active = null
      stick.style.transform = 'translate(0px, 0px)'
      this.touch.x = 0
      this.touch.y = 0
    }
    joy.addEventListener('pointerdown', (e) => {
      active = e.pointerId
      joy.setPointerCapture?.(e.pointerId)
      move(e)
      e.preventDefault()
    })
    joy.addEventListener('pointermove', move)
    joy.addEventListener('pointerup', end)
    joy.addEventListener('pointercancel', end)

    const hold = (btn, key) => {
      const on = (e) => { e.preventDefault(); this.touch[key] = true; btn.classList.add('held') }
      const off = (e) => { e?.preventDefault?.(); this.touch[key] = false; btn.classList.remove('held') }
      btn.addEventListener('pointerdown', on)
      btn.addEventListener('pointerup', off)
      btn.addEventListener('pointercancel', off)
      btn.addEventListener('pointerleave', off)
    }
    hold(this.el.touchGas, 'gas')
    hold(this.el.touchBrake, 'brake')
    hold(this.el.touchBoost, 'boost')
    hold(this.el.touchHandbrake, 'handbrake')
    this.el.touchAction.addEventListener('pointerdown', (e) => {
      e.preventDefault()
      this.onAction?.()
    })
  }

  ready() {
    this.el.loading.classList.add('gone')
  }

  buildMap(world) {
    const ctx = this.mapCtx
    const S = 512
    const range = 560
    const off = 280
    const scale = S / range
    const px = (x) => (x + off) * scale
    const pz = (z) => (z + off) * scale

    ctx.clearRect(0, 0, S, S)
    // water / land
    ctx.fillStyle = '#182a38'
    ctx.fillRect(0, 0, S, S)
    ctx.fillStyle = '#38343c'
    ctx.fillRect(0, 0, S, pz(232))
    // hills
    ctx.fillStyle = '#2f3a36'
    ctx.fillRect(0, 0, S, pz(-168))
    // beach
    ctx.fillStyle = '#a98d66'
    ctx.fillRect(0, pz(168), S, pz(232) - pz(168))
    // ocean
    const grad = ctx.createLinearGradient(0, pz(232), 0, S)
    grad.addColorStop(0, '#2b6070')
    grad.addColorStop(1, '#172b3f')
    ctx.fillStyle = grad
    ctx.fillRect(0, pz(232), S, S - pz(232))
    // city asphalt
    ctx.fillStyle = '#23232d'
    ctx.fillRect(px(-168), pz(-168), px(168) - px(-168), pz(168) - pz(-168))

    for (const b of world.blockTypes) {
      const x = px(b.x - CITY.blockSize / 2)
      const y = pz(b.z - CITY.blockSize / 2)
      const w = CITY.blockSize * scale
      if (b.type === 'park') ctx.fillStyle = '#36523f'
      else if (b.type === 'parking') ctx.fillStyle = '#383946'
      else if (b.type === 'plaza') ctx.fillStyle = '#4b4156'
      else ctx.fillStyle = '#54505d'
      ctx.fillRect(x, y, w, w)
      if (b.type === 'buildings' || b.type === 'landmark') {
        ctx.fillStyle = '#6a6473'
        const inset = 7 * scale
        ctx.fillRect(x + inset, y + inset, w - inset * 2, w - inset * 2)
        ctx.fillStyle = 'rgba(255,255,255,0.08)'
        ctx.fillRect(x + inset, y + inset, (w - inset * 2) * 0.28, (w - inset * 2) * 0.28)
      }
      if (b.type === 'plaza') {
        ctx.fillStyle = '#ff5f9d'
        ctx.fillRect(px(-16), pz(56), 32 * scale, 2)
      }
    }

    // roads grid
    ctx.strokeStyle = '#1a1b23'
    ctx.lineWidth = CITY.road * scale
    for (const r of CITY.roadCenters) {
      ctx.beginPath(); ctx.moveTo(px(-168), pz(r)); ctx.lineTo(px(168), pz(r)); ctx.stroke()
      ctx.beginPath(); ctx.moveTo(px(r), pz(-168)); ctx.lineTo(px(r), pz(168)); ctx.stroke()
    }
    ctx.strokeStyle = 'rgba(210,200,170,0.35)'
    ctx.lineWidth = 0.8
    for (const r of CITY.roadCenters) {
      ctx.beginPath(); ctx.moveTo(px(-168), pz(r)); ctx.lineTo(px(168), pz(r)); ctx.stroke()
      ctx.beginPath(); ctx.moveTo(px(r), pz(-168)); ctx.lineTo(px(r), pz(168)); ctx.stroke()
    }
    // shoreline
    ctx.strokeStyle = 'rgba(180,240,255,0.5)'
    ctx.lineWidth = 1.4
    ctx.beginPath(); ctx.moveTo(0, pz(232)); ctx.lineTo(S, pz(232)); ctx.stroke()
    // pier
    ctx.fillStyle = '#5d4430'
    ctx.fillRect(px(-83), pz(230), 10 * scale, 42 * scale)
    this.mapScale = scale
    this.mapReady = true
  }

  setText(id, value) {
    if (this.cache[id] === value) return
    this.cache[id] = value
    const node = this.el[id] || document.getElementById(id)
    if (node) node.textContent = value
  }

  setPlaying(isPlaying) {
    this.playing = isPlaying
    document.body.classList.toggle('playing', isPlaying)
    document.body.classList.toggle('title-mode', !isPlaying)
    if (isPlaying) this.el.title.classList.add('gone')
    else this.el.title.classList.remove('gone')
  }

  update(state) {
    if (!this.playing) return
    const s = state
    this.setText('speed', String(Math.round(Math.abs(s.speedKmh || 0))))
    this.setText('gear', s.gear || 'N')
    this.setText('cash', (s.cash ?? 0).toLocaleString('en-US'))
    this.setText('clock', s.clock || '19:42')
    this.setText('district', s.district || 'LOS SANTOS')

    const hp = clamp(Math.round(s.health ?? 100), 0, 100)
    const armor = clamp(Math.round(s.armor ?? 0), 0, 100)
    if (this.cache.hp !== hp) {
      this.cache.hp = hp
      this.el.healthBar.style.width = `${hp}%`
      this.el.healthValue.textContent = hp
    }
    if (this.cache.armor !== armor) {
      this.cache.armor = armor
      this.el.armorBar.style.width = `${armor}%`
      this.el.armorValue.textContent = armor
    }

    const wanted = s.wanted || 0
    if (this.cache.wanted !== wanted) {
      this.cache.wanted = wanted
      this.el.wanted.forEach((star, i) => star.classList.toggle('on', i < wanted))
    }

    if (s.vehicle) {
      this.el.vehiclePanel.classList.remove('hidden')
      const v = s.vehicle
      this.setText('vBrand', v.brand)
      this.setText('vName', v.name)
      this.setText('vClass', v.className)
      this.setText('vMode', v.drivetrain)
      const batt = clamp(Math.round(s.battery ?? 100), 0, 100)
      if (this.cache.batt !== batt) {
        this.cache.batt = batt
        this.el.batteryBar.style.transform = `scaleX(${batt / 100})`
        this.el.batteryValue.textContent = `${batt}%`
      }
      this.el.vehiclePanel.style.borderRightColor = `#${v.accent.toString(16).padStart(6, '0')}`
    } else {
      this.el.vehiclePanel.classList.add('hidden')
    }

    if (s.prompt) {
      this.el.interact.classList.add('show')
      this.setText('interactText', s.prompt)
      if (this.isTouch) this.el.touchAction.textContent = s.prompt.includes('EXIT') ? '↩' : 'E'
    } else {
      this.el.interact.classList.remove('show')
    }

    if (s.mission) {
      this.el.missionCard.classList.remove('hidden')
      this.setText('missionTitle', s.mission.title)
      this.setText('missionTarget', s.mission.target)
      this.setText('missionTimer', s.mission.timerText)
      this.setText('missionDistance', s.mission.distanceText)
      const prog = clamp(s.mission.progress, 0, 1)
      this.el.missionProgress.style.width = `${Math.max(2, prog * 100)}%`
    } else {
      this.el.missionCard.classList.add('hidden')
    }

    this.drawMinimap(s)
  }

  drawMinimap(s) {
    if (!this.mapReady) return
    const c = this.el.minimap
    const ctx = c.getContext('2d')
    const W = c.width
    const half = W / 2
    const zoom = 2.05
    ctx.save()
    ctx.clearRect(0, 0, W, W)
    ctx.beginPath()
    ctx.arc(half, half, half - 2, 0, Math.PI * 2)
    ctx.clip()
    ctx.fillStyle = '#111722'
    ctx.fillRect(0, 0, W, W)

    const px = (s.player.x + 280) * this.mapScale
    const pz = (s.player.z + 280) * this.mapScale
    ctx.translate(half, half)
    ctx.rotate(Math.PI - (s.player.heading || 0))
    ctx.scale(zoom, zoom)
    ctx.drawImage(this.mapCanvas, -px, -pz)

    // map markers in rotated space
    const drawDot = (wx, wz, color, size = 3.4, glow = false) => {
      const x = (wx + 280) * this.mapScale - px
      const z = (wz + 280) * this.mapScale - pz
      if (glow) {
        ctx.shadowColor = color
        ctx.shadowBlur = 12
      }
      ctx.fillStyle = color
      ctx.beginPath()
      ctx.arc(x, z, size, 0, Math.PI * 2)
      ctx.fill()
      ctx.shadowBlur = 0
    }
    if (s.markers?.shards) for (const p of s.markers.shards) drawDot(p.x, p.z, '#66f4ff', 2.2)
    if (s.markers?.traffic) {
      for (const p of s.markers.traffic) drawDot(p.x, p.z, p.police ? '#ff4f6a' : 'rgba(255,255,255,0.5)', p.police ? 3.2 : 2.3)
    }
    if (s.markers?.mission) {
      const mx = (s.markers.mission.x + 280) * this.mapScale - px
      const mz = (s.markers.mission.z + 280) * this.mapScale - pz
      ctx.save()
      ctx.translate(mx, mz)
      ctx.rotate(-(Math.PI - (s.player.heading || 0)))
      ctx.fillStyle = '#ffc857'
      ctx.shadowColor = '#ffc857'
      ctx.shadowBlur = 10
      ctx.beginPath()
      ctx.moveTo(0, -7); ctx.lineTo(6, 0); ctx.lineTo(0, 7); ctx.lineTo(-6, 0); ctx.closePath()
      ctx.fill()
      ctx.restore()
    }
    ctx.restore()

    // player arrow
    ctx.save()
    ctx.translate(half, half)
    ctx.fillStyle = '#ffffff'
    ctx.shadowColor = '#66f4ff'
    ctx.shadowBlur = 12
    ctx.beginPath()
    ctx.moveTo(0, -9)
    ctx.lineTo(6.5, 7)
    ctx.lineTo(0, 3.8)
    ctx.lineTo(-6.5, 7)
    ctx.closePath()
    ctx.fill()
    ctx.restore()
  }

  setPrompt(text) {
    this._prompt = text
  }

  toast(text, kind = '', duration = 2600) {
    const div = document.createElement('div')
    div.className = `toast ${kind}`
    div.textContent = text
    this.el.toastStack.appendChild(div)
    while (this.el.toastStack.children.length > 4) this.el.toastStack.firstChild.remove()
    const t1 = setTimeout(() => {
      div.classList.add('out')
      const t2 = setTimeout(() => div.remove(), 340)
      this.timeouts.add(t2)
    }, duration)
    this.timeouts.add(t1)
  }

  showVehicleCard(vehicle) {
    const t = vehicle.type
    this.el.vcName.textContent = t.name
    this.el.vcSub.textContent = `${t.brand} · ${t.className}`
    this.el.vcSpeed.textContent = t.spec.top
    this.el.vcAccel.textContent = t.spec.accel.toFixed(1)
    this.el.vcHandling.textContent = t.spec.handling
    this.el.vehicleCard.classList.add('show')
    clearTimeout(this._cardTimeout)
    this._cardTimeout = setTimeout(() => this.el.vehicleCard.classList.remove('show'), 3800)
  }

  showEnd(kind) {
    this.el.busted.classList.toggle('show', kind === 'busted')
    this.el.wasted.classList.toggle('show', kind === 'wasted')
  }

  hideEnd() {
    this.el.busted.classList.remove('show')
    this.el.wasted.classList.remove('show')
  }

  flash() {
    this.el.flash.classList.remove('go')
    void this.el.flash.offsetWidth
    this.el.flash.classList.add('go')
  }

  showCinematic(title, sub, duration = 2400) {
    this.el.cineTitle.textContent = title
    this.el.cineSub.textContent = sub
    this.el.cinematic.classList.add('show')
    clearTimeout(this._cineTimeout)
    this._cineTimeout = setTimeout(() => this.el.cinematic.classList.remove('show'), duration)
  }

  districtFor(x, z) {
    for (const d of DISTRICTS) if (d.test(x, z)) return d.name
    return 'LOS SANTOS'
  }
}

