function safeSpot(x, z) {
  let px = x
  let pz = z
  for (let i = 0; i < 12; i++) {
    const hit = world.colliders.some((c) => px > c.minX - 1 && px < c.maxX + 1 && pz > c.minZ - 1 && pz < c.maxZ + 1)
    if (!hit) break
    px += 7
    if (px > 160) { px = x; pz -= 7 }
    if (pz < -160) break
  }
  return { x: clamp(px, -225, 225), z: clamp(pz, -225, 224) }
}

