function missionLabelSprite(title, sub) {
  const { c, ctx } = canvas2d(512, 160)
  ctx.clearRect(0, 0, 512, 160)
  ctx.textAlign = 'center'
  ctx.font = '900 52px "Arial Black", Arial, sans-serif'
