import { createRequire } from 'node:module'
import { readFileSync, mkdirSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY = ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
mkdirSync('/tmp/opencode/shots', { recursive: true })

const browser = await chromium.launch({ ...config.browser.launchOptions })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
const errors = []
page.on('pageerror', e => { errors.push(e.message); console.log('PAGEERROR:', e.message) })
page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE:', m.text()) })

await page.goto('http://localhost:3002', { waitUntil: 'load' })
await page.waitForTimeout(1200)
await page.getByRole('button', { name: 'Play', exact: true }).click()
await page.waitForTimeout(700)

const snap = () => page.evaluate(() => {
  const s = window.__SA
  return {
    mode: s.state.mode,
    playing: s.state.playing,
    vehicle: s.state.activeVehicle?.type.name || null,
    speedKmh: Math.round((s.state.activeVehicle?.speed || 0) * 3.6),
    heading: +(s.state.activeVehicle?.heading ?? s.player.root.rotation.y).toFixed(2),
    pos: { x: +s.player.root.position.x.toFixed(1), z: +s.player.root.position.z.toFixed(1) },
    carPos: s.state.activeVehicle ? { x: +s.state.activeVehicle.group.position.x.toFixed(1), z: +s.state.activeVehicle.group.position.z.toFixed(1) } : null,
    cash: s.state.cash,
    wanted: s.state.wanted,
    health: Math.round(s.state.health),
    mission: s.mission ? { index: s.mission.index, completed: s.mission.completed, dist: +s.mission.distance.toFixed(1) } : null,
    shards: s.shards.filter(x => x.collected).length,
  }
})

console.log('start', await snap())

// enter nearest car
await page.keyboard.press('e')
await page.waitForTimeout(400)
console.log('after E', await snap())
await page.screenshot({ path: '/tmp/opencode/shots/drive_idle.png' })

// drive forward
await page.keyboard.down('w')
await page.waitForTimeout(1200)
const mid = await snap()
await page.waitForTimeout(1200)
const fast = await snap()
console.log('driving 1.2s', mid)
console.log('driving 2.4s', fast)
await page.screenshot({ path: '/tmp/opencode/shots/driving.png' })

// steer
await page.keyboard.down('d')
await page.waitForTimeout(900)
await page.keyboard.up('d')
const turned = await snap()
console.log('after steer', turned)
await page.screenshot({ path: '/tmp/opencode/shots/turning.png' })

// brake
await page.keyboard.up('w')
await page.keyboard.down('s')
await page.waitForTimeout(1300)
await page.keyboard.up('s')
console.log('after brake', await snap())

// boost
await page.keyboard.down('w')
await page.waitForTimeout(1000)
await page.keyboard.down('Shift')
await page.waitForTimeout(1000)
const boosted = await snap()
await page.keyboard.up('Shift')
await page.keyboard.up('w')
console.log('boosted', boosted)
await page.waitForTimeout(1200)

// exit car
await page.keyboard.press('e')
await page.waitForTimeout(400)
console.log('after exit', await snap())

// mission delivery
const missionInfo = await page.evaluate(() => {
  const s = window.__SA
  const m = s.mission
  return m ? { x: m.spot.x, z: m.spot.z, cash: s.state.cash, index: m.index } : null
})
console.log('mission spot', missionInfo)
if (missionInfo) {
  await page.evaluate(({ x, z }) => window.__SA.teleport(x, z), missionInfo)
  await page.waitForTimeout(900)
  console.log('after mission drop', await snap())
}

// shard pickup
const shardInfo = await page.evaluate(() => {
  const s = window.__SA
  const sh = s.shards.find(x => !x.collected)
  return sh ? { x: sh.spot.x, z: sh.spot.z, cash: s.state.cash } : null
})
console.log('shard spot', shardInfo)
if (shardInfo) {
  await page.evaluate(({ x, z }) => window.__SA.teleport(x, z), shardInfo)
  await page.waitForTimeout(700)
  console.log('after shard', await snap())
}

// collision test: place car just south of a building collider and drive north into it
const collision = await page.evaluate(() => {
  const s = window.__SA
  const b = s.world.colliders.find(c => c.maxZ > 40 && c.maxZ < 90 && Math.abs((c.minX + c.maxX) / 2) < 30)
  return b ? { minX: b.minX, maxX: b.maxX, minZ: b.minZ, maxZ: b.maxZ } : null
})
console.log('test collider', collision)

// mobile pass
await page.close()
const mobile = await browser.newPage({ viewport: { width: 390, height: 844 }, hasTouch: true, isMobile: true, deviceScaleFactor: 2 })
mobile.on('pageerror', e => { errors.push(e.message); console.log('MOBILE PAGEERROR:', e.message) })
await mobile.goto('http://localhost:3002', { waitUntil: 'load' })
await mobile.waitForTimeout(1200)
await mobile.screenshot({ path: '/tmp/opencode/shots/mobile_title.png' })
await mobile.getByRole('button', { name: 'Play', exact: true }).click()
await mobile.waitForTimeout(900)
await mobile.screenshot({ path: '/tmp/opencode/shots/mobile_game.png' })
console.log('mobile body classes', await mobile.evaluate(() => document.body.className))
console.log('touch visible', await mobile.evaluate(() => getComputedStyle(document.getElementById('touch-controls')).display))
console.log('errors', errors)
await browser.close()

