  v.heading = Math.PI
  v.group.rotation.y = v.heading
  v.speed = 0
  v.vel.set(0, 0, 0)
  return { minX: b.minX, maxX: b.maxX, minZ: b.minZ, maxZ: b.maxZ, cx }
})

