import { createRequire } from 'node:module'
import { readFileSync, mkdirSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY = ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
mkdirSync('/tmp/opencode/shots', { recursive: true })

const browser = await chromium.launch({ ...config.browser.launchOptions })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
const errors = []
page.on('pageerror', e => { errors.push(e.message); console.log('PAGEERROR:', e.message) })
page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE:', m.text()) })

await page.goto('http://localhost:3002', { waitUntil: 'load' })
await page.waitForTimeout(1200)
await page.getByRole('button', { name: 'Play', exact: true }).click()
await page.waitForTimeout(500)

await page.evaluate(() => {
  window.__snap = () => {
    const s = window.__SA
    return {
      mode: s.state.mode,
      playing: s.state.playing,
      elapsed: +s.state.elapsed.toFixed(2),
      vehicle: s.state.activeVehicle?.type.name || null,
      speedKmh: Math.round((s.state.activeVehicle?.speed || 0) * 3.6),
      heading: +(s.state.activeVehicle?.heading ?? s.player.root.rotation.y).toFixed(2),
      carPos: s.state.activeVehicle ? { x: +s.state.activeVehicle.group.position.x.toFixed(1), z: +s.state.activeVehicle.group.position.z.toFixed(1) } : null,
      cash: s.state.cash,
      wanted: s.state.wanted,
      police: s.state.police.length,
      health: Math.round(s.state.health),
      mission: s.mission ? { index: s.mission.index, completed: s.mission.completed, dist: +s.mission.distance.toFixed(1) } : null,
      shards: s.shards.filter(x => x.collected).length,
    }
  }
  window.__render = () => window.__SA.renderer.render(window.__SA.scene, window.__SA.camera)
})
const snap = () => page.evaluate(() => window.__snap())
const render = () => page.evaluate(() => window.__render())

console.log('start', await snap())

// enter the nearest showroom car through the real interaction path
await page.keyboard.press('e')
await page.waitForTimeout(150)
await page.evaluate(() => window.__SA.step(1 / 60, 1))
await render()
console.log('after E', await snap())
await page.screenshot({ path: '/tmp/opencode/shots/drive_idle.png' })

// drive forward 2 simulated seconds
console.log('drive 2s', await page.evaluate(() => {
  const s = window.__SA
  s.input.keys.add('w')
  s.step(1 / 60, 120)
  s.renderer.render(s.scene, s.camera)
  return window.__snap()
}))
await page.screenshot({ path: '/tmp/opencode/shots/driving.png' })

// steer right while driving
console.log('steer 1s', await page.evaluate(() => {
  const s = window.__SA
  s.input.keys.add('d')
  s.step(1 / 60, 60)
  s.input.keys.delete('d')
  s.renderer.render(s.scene, s.camera)
  return window.__snap()
}))
await page.screenshot({ path: '/tmp/opencode/shots/turning.png' })

// brake to a stop
console.log('brake 1.5s', await page.evaluate(() => {
  const s = window.__SA
  s.input.keys.delete('w')
  s.input.keys.add('s')
  s.step(1 / 60, 90)
  s.step(1 / 60, 1)
  s.input.keys.delete('s')
  s.renderer.render(s.scene, s.camera)
  return window.__snap()
}))

// boost
console.log('boost 1.5s', await page.evaluate(() => {
  const s = window.__SA
  s.input.keys.add('w')
  s.input.keys.add('shift')
  s.step(1 / 60, 90)
  s.input.keys.delete('shift')
  s.input.keys.delete('w')
  s.renderer.render(s.scene, s.camera)
  return window.__snap()
}))

// coast + handbrake, then exit with the real E path
await page.evaluate(() => {
  const s = window.__SA
  s.input.keys.add(' ')
  s.step(1 / 60, 120)
  s.input.keys.delete(' ')
  s.step(1 / 60, 30)
})
await page.keyboard.press('e')
await page.waitForTimeout(150)
await page.evaluate(() => window.__SA.step(1 / 60, 1))
render()
console.log('after exit', await snap())
await page.screenshot({ path: '/tmp/opencode/shots/after_exit.png' })

// mission delivery
const missionInfo = await page.evaluate(() => {
  const s = window.__SA
  return s.mission ? { x: s.mission.spot.x, z: s.mission.spot.z, reward: s.mission.reward, cash: s.state.cash } : null
})
console.log('mission spot', missionInfo)
if (missionInfo) {
  console.log('after mission drop', await page.evaluate(({ x, z }) => {
    const s = window.__SA
    s.teleport(x, z)
    s.step(1 / 60, 12)
    return window.__snap()
  }, missionInfo))
}

// shard pickup
const shardInfo = await page.evaluate(() => {
  const s = window.__SA
  const sh = s.shards.find(x => !x.collected)
  return sh ? { x: sh.spot.x, z: sh.spot.z, cash: s.state.cash } : null
})
console.log('shard spot', shardInfo)
if (shardInfo) {
  console.log('after shard', await page.evaluate(({ x, z }) => {
    const s = window.__SA
    s.teleport(x, z)
    s.step(1 / 60, 12)
    return window.__snap()
  }, shardInfo))
}

// collision: enter the cyber truck, place it south of a building, floor it north
const collision = await page.evaluate(() => {
  const s = window.__SA
  const v = s.vehicles.find(x => x.type.id === 'cyber') || s.vehicles.find(x => !x.police)
  v.group.position.set(v.group.position.x, 0.02, v.group.position.z)
  s.enterVehicle(v)
  const b = s.world.colliders.find(c => c.maxZ > 95 && c.maxZ < 150 && Math.abs((c.minX + c.maxX) / 2) < 90)
  if (!b) return null
  const cx = (b.minX + b.maxX) / 2
  v.group.position.set(cx, 0.02, b.maxZ + 9)
  v.heading = Math.PI
  v.group.rotation.y = v.heading
  v.speed = 0
  v.vel.set(0, 0, 0)
  s.input.keys.clear()
  s.input.keys.add('w')
  s.step(1 / 60, 180)
  s.input.keys.delete('w')
  s.renderer.render(s.scene, s.camera)
  return { ...window.__snap(), building: { minX: +b.minX.toFixed(1), maxX: +b.maxX.toFixed(1), minZ: +b.minZ.toFixed(1), maxZ: +b.maxZ.toFixed(1) } }
})
console.log('collision result', collision)
await page.screenshot({ path: '/tmp/opencode/shots/collision.png' })

// police / wanted
console.log('wanted', await page.evaluate(() => {
  const s = window.__SA
  s.addWanted(2, 'TEST CRIME')
  s.step(1 / 60, 120)
  return window.__snap()
}))

await page.close()

// mobile pass
const mobile = await browser.newPage({ viewport: { width: 390, height: 844 }, hasTouch: true, isMobile: true, deviceScaleFactor: 2 })
mobile.on('pageerror', e => { errors.push(e.message); console.log('MOBILE PAGEERROR:', e.message) })
await mobile.goto('http://localhost:3002', { waitUntil: 'load' })
await mobile.waitForTimeout(1200)
await mobile.screenshot({ path: '/tmp/opencode/shots/mobile_title.png' })
await mobile.getByRole('button', { name: 'Play', exact: true }).click()
await mobile.waitForTimeout(900)
await mobile.screenshot({ path: '/tmp/opencode/shots/mobile_game.png' })
console.log('mobile body classes', await mobile.evaluate(() => document.body.className))
console.log('touch visible', await mobile.evaluate(() => getComputedStyle(document.getElementById('touch')).display))
console.log('errors', errors)
await browser.close()

