import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY = ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()

const browser = await chromium.launch({ ...config.browser.launchOptions })
const errors = []

const page = await browser.newPage({ viewport: { width: 1280, height: 800 } })
page.on('pageerror', e => errors.push(e.message))
await page.goto('http://localhost:3002', { waitUntil: 'load' })
await page.waitForTimeout(1200)
await page.getByRole('button', { name: 'Play', exact: true }).click()
await page.waitForTimeout(400)

console.log('foot move', await page.evaluate(() => {
  const s = window.__SA
  const x0 = s.player.root.position.x, z0 = s.player.root.position.z
  s.input.keys.add('w')
  s.step(1 / 60, 60)
  s.input.keys.delete('w')
  const walked = Math.hypot(s.player.root.position.x - x0, s.player.root.position.z - z0)
  const x1 = s.player.root.position.x, z1 = s.player.root.position.z
  s.input.keys.add('w'); s.input.keys.add('shift')
  s.step(1 / 60, 60)
  s.input.keys.delete('w'); s.input.keys.delete('shift')
  const sprinted = Math.hypot(s.player.root.position.x - x1, s.player.root.position.z - z1)
  return { walked: +walked.toFixed(2), sprinted: +sprinted.toFixed(2), mode: s.state.mode }
}))

console.log('jump', await page.evaluate(() => {
  const s = window.__SA
  s.input.jumpQueued = true
  s.step(1 / 60, 10)
  const air = { y: +s.player.root.position.y.toFixed(2), vy: +s.playerState.vy.toFixed(2), grounded: s.playerState.grounded }
  s.step(1 / 60, 120)
  return { air, landed: { y: +s.player.root.position.y.toFixed(2), grounded: s.playerState.grounded } }
}))

console.log('bike enter/exit', await page.evaluate(() => {
  const s = window.__SA
  const bike = s.vehicles.find(v => v.type.id === 'mantis')
  s.player.root.position.set(bike.group.position.x, 0.29, bike.group.position.z + 2)
  s.player.root.position.z = bike.group.position.z + 3.2
  s.step(1 / 60, 1)
  s.enterVehicle(bike)
  const entered = { mode: s.state.mode, hidden: !s.player.root.visible }
  s.input.keys.add('w')
  s.step(1 / 60, 60)
  s.input.keys.delete('w')
  const speed = Math.round((bike.speed || 0) * 3.6)
  s.exitVehicle()
  s.step(1 / 60, 1)
  return { entered, speed, exited: { mode: s.state.mode, visible: s.player.root.visible } }
}))

console.log('busted/respawn', await page.evaluate(() => {
  const s = window.__SA
  s.addWanted(2, 'TEST CRIME')
  const cop = s.state.police[0]
  s.player.root.position.set(cop.group.position.x + 2, 0.29, cop.group.position.z)
  s.step(1 / 60, 90)
  const down = { mode: s.state.mode, wanted: s.state.wanted, cops: s.state.police.length, cash: s.state.cash, timer: +s.state.endTimer.toFixed(1) }
  s.step(1 / 60, 360)
  return { down, respawned: { mode: s.state.mode, wanted: s.state.wanted, health: Math.round(s.state.health), playing: s.state.playing } }
}))

// mobile touch gas
await page.close()
const mobile = await browser.newPage({ viewport: { width: 390, height: 844 }, hasTouch: true, isMobile: true, deviceScaleFactor: 2 })
mobile.on('pageerror', e => errors.push('mobile: ' + e.message))
await mobile.goto('http://localhost:3002', { waitUntil: 'load' })
await mobile.waitForTimeout(1200)
await mobile.getByRole('button', { name: 'Play', exact: true }).click()
await mobile.waitForTimeout(400)
console.log('mobile touch drive', await mobile.evaluate(() => {
  const s = window.__SA
  const v = s.vehicles[0]
  s.enterVehicle(v)
  s.step(1 / 60, 1)
  document.getElementById('touch-gas').dispatchEvent(new PointerEvent('pointerdown', { bubbles: true, pointerId: 1 }))
  s.step(1 / 60, 90)
  const gas = s.state.activeVehicle.speed
  document.getElementById('touch-gas').dispatchEvent(new PointerEvent('pointerup', { bubbles: true, pointerId: 1 }))
  s.step(1 / 60, 2)
  return { speedKmh: Math.round(gas * 3.6), gasReleased: !s.ui?.touch?.gas }
}))
console.log('errors', errors)
await browser.close()

