input.command:
cat > /tmp/opencode/bike_shot.mjs <<'EOF'
import { createRequire } from 'node:module'
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY = ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const browser = await chromium.launch({ ...config.browser.launchOptions })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
page.on('pageerror', e => console.log('PAGEERROR:', e.message))
await page.goto('http://localhost:3002', { waitUntil: 'load' })
await page.waitForTimeout(1200)
await page.getByRole('button', { name: 'Play', exact: true }).click()
await page.waitForTimeout(500)
const r = await page.evaluate(() => {
  const s = window.__SA
  const bike = s.vehicles.find(v => v.type.id === 'mantis')
  s.enterVehicle(bike)
  s.step(1 / 60, 2)
  s.setCamera(bike.heading - Math.PI + 0.6, 0.16, 5.8)
  s.step(1 / 60, 2)
  s.renderer.render(s.scene, s.camera)
  return { mode: s.state.mode, visible: s.player.root.visible, riderPos: s.player.root.position.toArray().map(n => +n.toFixed(2)), bikePos: bike.group.position.toArray().map(n => +n.toFixed(2)) }
})
console.log(r)
await page.waitForTimeout(100)
await page.screenshot({ path: '/tmp/opencode/shots/bike_rider.png' })
await browser.close()
EOF
cd /tmp/opencode && node bike_shot.mjs 2>&1 | tail -5

